"""Unique facts M-498 through M-625."""
from __future__ import annotations


def facts() -> dict[int, dict]:
    F: dict[int, dict] = {}

    def a(n, stmt, exq, exa, gq, ga, trap, q1, a1, q2, a2):
        F[n] = dict(stmt=stmt, exq=exq, exa=exa, gq=gq, ga=ga, trap=trap, q1=q1, a1=a1, q2=q2, a2=a2)

    # L number theory: divisibility & primes
    a(498, r"For $a,b\in\mathbb{Z}$ with $a\neq 0$, $a$ divides $b$ (write $a\mid b$) iff $b=aq$ for some $q\in\mathbb{Z}$. Then $b$ is a multiple of $a$. Divisibility is reflexive and transitive; $a\mid b$ and $b\mid a$ iff $a=\pm b$. Every integer divides $0$; only $\pm 1$ divide $1$.",
      r"Does $12\mid 84$? Does $12\mid 90$?",
      r"$84=12\cdot 7$, so yes. $90=12\cdot 7+6$, so no.",
      r"If $a\mid b$ and $a\mid c$, then $a$ divides", r"$bx+cy$ for every $x,y\in\mathbb{Z}$ (linear combinations).",
      r"Concluding $a\nmid b$ from $a>b>0$ while forgetting $b=0$ is a multiple of every $a$.",
      r"List the positive divisors of $18$.", r"$1,2,3,6,9,18$.",
      r"Does $8\mid 0$? Does $0\mid 8$?", r"Yes; no ($0$ divides only $0$).")
    a(499, r"Division algorithm: for $a\in\mathbb{Z}$ and $d>0$ there exist unique $q,r\in\mathbb{Z}$ with $a=dq+r$ and $0\le r<d$. Here $q=\lfloor a/d\rfloor$ and $r=a-dq$ is the remainder. The remainder is $0$ iff $d\mid a$.",
      r"Divide $47$ by $9$, and divide $-17$ by $5$.",
      r"$47=5\cdot 9+2$. For $-17$: $-17=(-4)\cdot 5+3$, since $-20+3=-17$ and $0\le 3<5$ (not remainder $-2$).",
      r"$a=dq+r$ with $0\le r<d$ is unique. If $100=7q+r$, then $r$ equals", r"$2$, because $98=14\cdot 7$ and $100-98=2$.",
      r"Allowing a negative remainder, or using $r<|a|$ instead of $r<d$.",
      r"Remainder of $1001$ on division by $13$.", r"$13\cdot 77=1001$, remainder $0$.",
      r"What is $\lfloor -17/5\rfloor$?", r"$-4$, matching $q$ above.")
    a(500, r"The greatest common divisor $\gcd(a,b)$ is the largest positive integer dividing both (set $\gcd(0,0)$ undefined or $0$ by convention). $\gcd(a,b)=\gcd(|a|,|b|)=\gcd(b,a)=\gcd(a,b-aq)$. Integers are coprime when $\gcd=1$. $\gcd(a,0)=|a|$ for $a\neq 0$.",
      r"Compute $\gcd(54,24)$ by listing, then by subtracting.",
      r"Positive common divisors of $54,24$ are $1,2,3,6$, so $\gcd=6$. Also $\gcd(54,24)=\gcd(24,6)=\gcd(6,0)=6$.",
      r"$\gcd(0,12)$ equals", r"$12$.",
      r"Reporting a negative gcd, or taking $\gcd(8,12)=8$ because $8<12$.",
      r"$\gcd(35,10)$.", r"$5$.",
      r"Is $\gcd(9,-6)$ equal to $\gcd(9,6)$?", r"Yes, both $3$.")
    a(501, r"The least common multiple $\mathrm{lcm}(a,b)$ is the smallest positive common multiple. For $a,b\neq 0$, $\gcd(a,b)\cdot\mathrm{lcm}(a,b)=|ab|$. $\mathrm{lcm}$ is a multiple of each; any common multiple is a multiple of the lcm.",
      r"Find $\mathrm{lcm}(12,18)$ two ways.",
      r"Multiples of $12$: $12,24,36,\ldots$; of $18$: $18,36,\ldots$. So $36$. Check: $\gcd(12,18)=6$ and $6\cdot 36=216=12\cdot 18$.",
      r"$\mathrm{lcm}(8,12)$ equals", r"$24$.",
      r"Using $\mathrm{lcm}(a,b)=ab$ even when $\gcd>1$ (that overcounts).",
      r"$\mathrm{lcm}(7,3)$.", r"$21$ (coprime, so product).",
      r"Does $\mathrm{lcm}(6,10,15)=30$?", r"Yes: $30$ is a common multiple and no smaller positive one exists.")
    a(502, r"A prime $p>1$ has no positive divisors other than $1$ and $p$. An integer $n>1$ is composite otherwise. $1$ is neither. $a,b$ are coprime (relatively prime) iff $\gcd(a,b)=1$, even if both are composite. Euclid: if $p\mid ab$ then $p\mid a$ or $p\mid b$. Infinitely many primes.",
      r"Is $91$ prime? Are $8$ and $15$ coprime?",
      r"$91=7\cdot 13$, composite. $\gcd(8,15)=1$, so coprime (neither need be prime).",
      r"If a prime $p$ divides $n!+1$ for $n\ge 2$, then $p$ is", r"larger than $n$ (else $p\mid n!$ so $p\mid 1$).",
      r"Calling $1$ prime, or thinking coprime means ‘both prime’.",
      r"Smallest prime dividing $51$.", r"$3$, since $51=3\cdot 17$.",
      r"Are $14$ and $15$ coprime?", r"Yes, $\gcd=1$.")
    a(503, r"Euclidean algorithm: $\gcd(a,b)=\gcd(b,a\bmod b)$, iterating until remainder $0$; the last nonzero remainder is the gcd. It computes $\gcd$ without factoring. The number of steps is $O(\log\max(|a|,|b|))$.",
      r"Compute $\gcd(252,198)$ by the Euclidean algorithm.",
      r"$252=1\cdot 198+54$, $198=3\cdot 54+36$, $54=1\cdot 36+18$, $36=2\cdot 18+0$. Last nonzero remainder $18$.",
      r"$\gcd(1071,462)$ equals", r"$21$: $1071=2\cdot 462+147$, $462=3\cdot 147+21$, $147=7\cdot 21$.",
      r"Stopping at a remainder that still has a common factor rather than continuing to $0$.",
      r"$\gcd(1001,91)$.", r"$91$, because $1001=11\cdot 91$.",
      r"Why $\gcd(a,b)=\gcd(b,a-qb)$?", r"Any common divisor of $a,b$ divides $a-qb$, and conversely.")
    a(504, r"Bézout: $\gcd(a,b)$ is an integer linear combination: there exist $x,y\in\mathbb{Z}$ with $ax+by=\gcd(a,b)$. The set of all combinations $ax+by$ is exactly $\gcd(a,b)\mathbb{Z}$. In particular $ax+by=1$ is solvable iff $a,b$ are coprime. Coefficients come from back-substituting the Euclidean algorithm.",
      r"Find $x,y$ with $56x+15y=1$.",
      r"$56=3\cdot 15+11$, $15=1\cdot 11+4$, $11=2\cdot 4+3$, $4=1\cdot 3+1$. Back-sub: $1=4-3=4-(11-2\cdot 4)=3\cdot 4-11=3(15-11)-11=3\cdot 15-4\cdot 11=3\cdot 15-4(56-3\cdot 15)=15\cdot 15-4\cdot 56$. So $x=-4$, $y=15$.",
      r"$6x+9y=2$ has integer solutions?", r"No: $\gcd(6,9)=3\nmid 2$.",
      r"Claiming Bézout coefficients are unique (they are not: add $b/d$ and subtract $a/d$).",
      r"Express $\gcd(12,8)$ as $12x+8y$.", r"$4=12\cdot 1+8\cdot(-1)$, for instance.",
      r"Does $10x+15y=5$ have solutions?", r"Yes, $3\mid 5$; e.g. $x=2$, $y=-1$.")
    a(505, r"Fundamental theorem of arithmetic: every integer $n>1$ factors uniquely as $n=p_1^{e_1}\cdots p_k^{e_k}$ with primes $p_1<\cdots<p_k$ and $e_i\ge 1$. Uniqueness is up to order. From this, $a\mid b$ iff every exponent in $a$ is $\le$ the corresponding exponent in $b$.",
      r"Factor $360$ completely.",
      r"$360=36\cdot 10=2^2 3^2\cdot 2\cdot 5=2^3\cdot 3^2\cdot 5$.",
      r"$84$ factors as", r"$2^2\cdot 3\cdot 7$.",
      r"Treating $1$ as a prime in the factorization, or forgetting a repeated factor ($12=2\cdot 6$ is incomplete).",
      r"Prime factorization of $1001$.", r"$7\cdot 11\cdot 13$.",
      r"Does $2^2\cdot 3$ divide $2^3\cdot 3^2\cdot 5$?", r"Yes: exponents $2\le 3$ and $1\le 2$.")
    a(506, r"If $n=\prod p_i^{e_i}$, the number of positive divisors is $\tau(n)=d(n)=\prod(e_i+1)$. Each divisor is $\prod p_i^{a_i}$ with $0\le a_i\le e_i$. $d$ is multiplicative: $\gcd(m,n)=1\Rightarrow d(mn)=d(m)d(n)$.",
      r"How many positive divisors has $360=2^3 3^2 5$?",
      r"$(3+1)(2+1)(1+1)=4\cdot 3\cdot 2=24$.",
      r"$d(p^{k})$ for $p$ prime equals", r"$k+1$.",
      r"Adding the exponents instead of adding $1$ to each, or counting $1$ and $n$ twice.",
      r"$d(84)$ for $84=2^2\cdot 3\cdot 7$.", r"$(2+1)(1+1)(1+1)=12$.",
      r"Which $n<20$ has the most divisors?", r"$12$ and $18$ each have $6$; $16=2^4$ has $5$. So $12$ or $18$.")
    a(507, r"The sum of positive divisors is $\sigma(n)=\prod\frac{p_i^{e_i+1}-1}{p_i-1}$ when $n=\prod p_i^{e_i}$. $\sigma$ is multiplicative. $n$ is perfect when $\sigma(n)=2n$ (equivalently the proper-divisor sum is $n$).",
      r"Compute $\sigma(12)$ by listing and by formula.",
      r"Divisors $1,2,3,4,6,12$ sum to $28$. Formula: $12=2^2\cdot 3$, $\sigma=(2^3-1)/(2-1)\cdot(3^2-1)/(3-1)=7\cdot 4=28$.",
      r"$\sigma(p^k)$ equals", r"$(p^{k+1}-1)/(p-1)=1+p+\cdots+p^k$.",
      r"Using $\sigma(n)=d(n)\cdot n/2$ as if every divisor paired with $n$ (false when $n$ is a square: $\sqrt{n}$ is unpaired).",
      r"$\sigma(84)$, $84=2^2\cdot 3\cdot 7$.", r"$(7)(4)(8)=224$.",
      r"Is $6$ perfect?", r"Yes: $\sigma(6)=12=2\cdot 6$.")

    # L congruences
    a(508, r"$a\equiv b\pmod{n}$ means $n\mid(a-b)$, for $n>0$. Equivalence relation on $\mathbb{Z}$: reflexive, symmetric, transitive. $a\equiv b\pmod{n}$ iff $a$ and $b$ leave the same remainder on division by $n$. $a\equiv 0\pmod{n}$ iff $n\mid a$.",
      r"Is $23\equiv 5\pmod{9}$? Is $23\equiv 8\pmod{9}$?",
      r"$23-5=18$ divisible by $9$, yes. $23-8=15$ not divisible by $9$, no. Remainders: $23=2\cdot 9+5$.",
      r"$100\equiv ?\pmod{7}$ in $\{0,1,\ldots,6\}$", r"$2$, because $98=14\cdot 7$ and $100-98=2$.",
      r"Reducing only one side, or confusing $a\equiv b\pmod{n}$ with $a=bn$.",
      r"$17\equiv -1\pmod{9}$?", r"Yes, $18$ is a multiple of $9$.",
      r"Does $a\equiv b\pmod{1}$ always hold?", r"Yes: $1$ divides every difference.")
    a(509, r"The residue class of $a$ modulo $n$ is $[a]_n=\{a+kn:k\in\mathbb{Z}\}$. There are exactly $n$ distinct classes, represented by $\{0,1,\ldots,n-1\}$ (complete residues) or by any $n$ pairwise incongruent integers. $\mathbb{Z}/n\mathbb{Z}$ is the set of classes.",
      r"Which of $7,11,15,-1$ represent the same class mod $4$?",
      r"$7\equiv 3$, $11\equiv 3$, $15\equiv 3$, $-1\equiv 3\pmod{4}$. All four are $[3]_4$.",
      r"A complete set of residues mod $5$ is", r"e.g. $\{0,1,2,3,4\}$ or $\{5,6,-3,13,9\}$.",
      r"Thinking $[-1]_n$ is a different extra class besides $[n-1]_n$.",
      r"How many distinct classes mod $12$ contain an even integer?", r"$6$: $[0],[2],\ldots,[10]$.",
      r"Is $\{2,4,6,8\}$ a complete residue system mod $4$?", r"No: all even, only classes $[0]$ and $[2]$.")
    a(510, r"Congruences may be added, subtracted, and multiplied: $a\equiv b$, $c\equiv d\pmod{n}$ imply $a\pm c\equiv b\pm d$ and $ac\equiv bd\pmod{n}$. You may cancel a factor $k$ in $ka\equiv kb\pmod{n}$ iff $\gcd(k,n)=1$; in general you cancel $\gcd(k,n)$ from the modulus as well. Raising to a positive integer power preserves congruence.",
      r"From $7\equiv -1\pmod{8}$, compute $7^4\pmod{8}$.",
      r"$7\equiv -1$ so $7^4\equiv(-1)^4=1\pmod{8}$. Directly $7^2=49\equiv 1$, then $7^4\equiv 1$.",
      r"$6\equiv 2\pmod{4}$. Cancel $2$ to get $3\equiv 1\pmod{4}$?", r"False. Correct: divide congruence and modulus by $\gcd(2,4)=2$, getting $3\equiv 1\pmod{2}$, which is true.",
      r"Canceling a non-coprime factor and keeping the same modulus.",
      r"$11+9\pmod{12}$.", r"$8$, since $20\equiv 8$.",
      r"$5\cdot 7\pmod{12}$.", r"$35\equiv 11\pmod{12}$.")
    a(511, r"$a$ has a multiplicative inverse modulo $n$ iff $\gcd(a,n)=1$. Then some $x$ has $ax\equiv 1\pmod{n}$; write $x\equiv a^{-1}\pmod{n}$. Compute $x$ by Bézout (extended Euclidean). The inverse is unique mod $n$.",
      r"Find the inverse of $5$ modulo $14$.",
      r"$\gcd(5,14)=1$. Trial: $5\cdot 3=15\equiv 1\pmod{14}$, so $5^{-1}\equiv 3$. Extended Euclid: $14=2\cdot 5+4$, $5=1\cdot 4+1$, $1=5-4=5-(14-2\cdot 5)=3\cdot 5-14$.",
      r"Does $6$ have an inverse mod $15$?", r"No: $\gcd(6,15)=3\neq 1$.",
      r"Writing $a^{-1}=1/a$ as a rational instead of an integer residue.",
      r"Inverse of $3$ mod $10$.", r"$7$, because $21\equiv 1$.",
      r"Inverse of $11$ mod $26$.", r"$19$: $11\cdot 19=209=8\cdot 26+1$.")
    a(512, r"The linear congruence $ax\equiv b\pmod{n}$ is solvable iff $d=\gcd(a,n)$ divides $b$. If so, there are exactly $d$ solutions modulo $n$, equally spaced by $n/d$. Reducing by $d$ yields an invertible congruence modulo $n/d$.",
      r"Solve $4x\equiv 6\pmod{10}$.",
      r"$d=\gcd(4,10)=2\mid 6$, so two solutions. Divide by $2$: $2x\equiv 3\pmod{5}$. Inverse of $2$ mod $5$ is $3$, so $x\equiv 9\equiv 4\pmod{5}$. Lift: $x\equiv 4$ or $9\pmod{10}$. Check: $16\equiv 6$, $36\equiv 6$.",
      r"$6x\equiv 5\pmod{9}$ has how many solutions?", r"None: $\gcd(6,9)=3\nmid 5$.",
      r"Reporting one solution when $d>1$, or dividing the modulus without dividing $a$ and $b$.",
      r"Number of solutions of $9x\equiv 6\pmod{12}$.", r"$\gcd(9,12)=3\mid 6$, so three solutions mod $12$.",
      r"$x\equiv 1\pmod{n}$ is $1\cdot x\equiv 1$; how many solutions?", r"One: $x\equiv 1$.")
    a(513, r"To solve $ax\equiv b\pmod{n}$: compute $d=\gcd(a,n)$. If $d\nmid b$, no solution. If $d\mid b$, divide the whole congruence by $d$ to get $a'x\equiv b'\pmod{n'}$ with $\gcd(a',n')=1$, invert $a'$ mod $n'$, then list $x_0, x_0+n',\ldots,x_0+(d-1)n'$ modulo $n$.",
      r"Solve $15x\equiv 25\pmod{35}$.",
      r"$d=\gcd(15,35)=5\mid 25$. Divide: $3x\equiv 5\pmod{7}$. Inverse of $3$ mod $7$ is $5$ ($15\equiv 1$), so $x\equiv 25\equiv 4\pmod{7}$. Five solutions: $x\equiv 4,11,18,25,32\pmod{35}$.",
      r"$8x\equiv 4\pmod{12}$. Solutions?", r"$\gcd(8,12)=4\mid 4$, four solutions. Divide by $4$: $2x\equiv 1\pmod{3}$. Inverse of $2$ mod $3$ is $2$, so $x\equiv 2\pmod{3}$, hence $x\equiv 2,5,8,11\pmod{12}$. Check $8\cdot 2=16\equiv 4$.",
      r"Forgetting to list all $d$ lifts after solving the reduced congruence.",
      r"Solve $6x\equiv 9\pmod{21}$.", r"$d=3\mid 9$. $2x\equiv 3\pmod{7}$, $x\equiv 5\pmod{7}$ (since $2\cdot 5=10\equiv 3$). Solutions $5,12,19\pmod{21}$.",
      r"Particular solution of $7x\equiv 1\pmod{26}$.", r"$x\equiv 15$, because $7\cdot 15=105=4\cdot 26+1$.")
    a(514, r"Chinese remainder theorem: if $\gcd(m,n)=1$, then the system $x\equiv a\pmod{m}$, $x\equiv b\pmod{n}$ has a unique solution modulo $mn$. Construct $x=a n(n^{-1}\bmod m)+b m(m^{-1}\bmod n)$, or solve sequentially. The map $\mathbb{Z}/mn\mathbb{Z}\to\mathbb{Z}/m\mathbb{Z}\times\mathbb{Z}/n\mathbb{Z}$ is a ring isomorphism.",
      r"Solve $x\equiv 2\pmod{5}$, $x\equiv 3\pmod{7}$.",
      r"Modulus $35$. Write $x=7k+3$. Then $7k+3\equiv 2\pmod{5}$, $2k\equiv -1\equiv 4\pmod{5}$, $k\equiv 2\pmod{5}$, $k=5t+2$, $x=35t+17$. Check: $17\equiv 2\pmod{5}$, $17\equiv 3\pmod{7}$.",
      r"The system $x\equiv 1\pmod{4}$, $x\equiv 3\pmod{5}$ has unique solution mod", r"$20$. Indeed $x\equiv 13\pmod{20}$.",
      r"Applying CRT when moduli are not coprime (need the compatibility $a\equiv b\pmod{\gcd}$ instead).",
      r"$x\equiv 0\pmod{3}$, $x\equiv 1\pmod{4}$.", r"$x\equiv 9\pmod{12}$.",
      r"How many solutions mod $15$ has $x\equiv 2\pmod{3}$, $x\equiv 2\pmod{5}$?", r"One: $x\equiv 2\pmod{15}$ (same remainder, coprime moduli).")
    a(515, r"A general system $x\equiv a_i\pmod{n_i}$ is solvable iff $a_i\equiv a_j\pmod{\gcd(n_i,n_j)}$ for all pairs. The solution, if it exists, is unique modulo $\mathrm{lcm}(n_1,\ldots,n_k)$. Pairwise coprime moduli recover classical CRT and modulus $\prod n_i$.",
      r"Solve $x\equiv 2\pmod{4}$, $x\equiv 4\pmod{6}$.",
      r"$\gcd(4,6)=2$ divides $2-4=-2$, so solvable; modulus $\mathrm{lcm}(4,6)=12$. $x=6t+4$, then $6t+4\equiv 2\pmod{4}\Rightarrow 2t\equiv 2\pmod{4}\Rightarrow t\equiv 1\pmod{2}$, so $x\equiv 10\pmod{12}$.",
      r"$x\equiv 1\pmod{4}$, $x\equiv 3\pmod{6}$ is", r"inconsistent: $1\not\equiv 3\pmod{2}$.",
      r"Using modulus $n_1 n_2$ when $\gcd>1$ (the true period is the lcm, strictly smaller).",
      r"$x\equiv 1\pmod{6}$, $x\equiv 7\pmod{10}$.", r"Compatible: $1\equiv 7\pmod{2}$. Then $x=10k+7\equiv 1\pmod{6}\Rightarrow 4k\equiv 0\pmod{6}\Rightarrow k\equiv 0\pmod{3}$, so $x\equiv 7\pmod{30}$.",
      r"Three congruences $x\equiv 1\pmod{2}$, $x\equiv 1\pmod{3}$, $x\equiv 1\pmod{5}$.", r"$x\equiv 1\pmod{30}$.")
    a(516, r"To compute $a^k\bmod n$, use successive squaring: write $k$ in binary and multiply the needed squares. Reduce mod $n$ after every multiplication. Euler/Fermat can shrink the exponent when $\gcd(a,n)=1$. Patterns in the last digits are $a^k\bmod 10$ (or $100$).",
      r"Compute $3^8\bmod 7$ by squaring.",
      r"$3^2\equiv 2$, $3^4\equiv 4$, $3^8\equiv 16\equiv 2\pmod{7}$. (Alternatively $3^3\equiv -1$, $3^6\equiv 1$, $3^8\equiv 3^2\equiv 2$.)",
      r"$7^{20}\bmod 10$ (last digit of $7^{20}$)", r"Cycle of last digits of $7$: $7,9,3,1$ of length $4$. $20\equiv 0\pmod{4}$, last digit $1$.",
      r"Computing $a^k$ in $\mathbb{Z}$ first then reducing — overflow and wasted work — or reducing the exponent mod $n$ instead of mod $\phi(n)$.",
      r"$2^{10}\bmod 13$.", r"$1024\bmod 13$: $13\cdot 78=1014$, remainder $10$. Or $2^4=16\equiv 3$, $2^8\equiv 9$, $2^{10}\equiv 9\cdot 4=36\equiv 10$.",
      r"$5^6\bmod 8$.", r"$5\equiv -3$, or $5^2=25\equiv 1$, so $5^6\equiv 1$.")

    # L Euler/Fermat
    a(517, r"Fermat's little theorem: if $p$ is prime and $p\nmid a$, then $a^{p-1}\equiv 1\pmod{p}$. Equivalently $a^p\equiv a\pmod{p}$ for all $a$ (including multiples of $p$). Useful reduction: $a^k\equiv a^{k\bmod(p-1)}\pmod{p}$ when $p\nmid a$.",
      r"Compute $2^{13}\bmod 11$.",
      r"$11$ prime, $11\nmid 2$, so $2^{10}\equiv 1\pmod{11}$. Then $2^{13}=2^{10}\cdot 2^3\equiv 8\pmod{11}$.",
      r"$3^{16}\bmod 17$ equals", r"$1$, by Fermat ($17-1=16$).",
      r"Using $a^{n-1}\equiv 1\pmod{n}$ when $n$ is composite (false in general: $2^{8}\not\equiv 1\pmod{9}$).",
      r"$4^{6}\bmod 7$.", r"$1$, by Fermat ($7-1=6$).",
      r"Does $a^p\equiv a\pmod{p}$ hold for $a=14$, $p=7$?", r"Yes, both sides $0$.")
    a(518, r"Euler's totient $\phi(n)$ counts integers in $\{1,\ldots,n-1\}$ coprime to $n$ (and $\phi(1)=1$). Equivalently $\phi(n)=|(\mathbb{Z}/n\mathbb{Z})^\times|$. $\phi(p)=p-1$, $\phi(p^k)=p^k-p^{k-1}=p^{k-1}(p-1)$, and $\phi$ is multiplicative on coprime arguments.",
      r"List the units counted by $\phi(12)$ and compute $\phi(12)$.",
      r"$\{1,5,7,11\}$, so $\phi(12)=4$. Formula: $12=2^2\cdot 3$, $\phi=12(1-1/2)(1-1/3)=4$.",
      r"$\phi(p)$ for prime $p$ is", r"$p-1$.",
      r"Counting $0$ among the totatives, or using $\phi(p^k)=p^k-1$.",
      r"$\phi(10)$.", r"$4$: residues $1,3,7,9$.",
      r"$\phi(1)+\phi(2)+\phi(5)+\phi(10)$ equals", r"$1+1+4+4=10$, illustrating $\sum_{d\mid n}\phi(d)=n$ for $n=10$.")
    a(519, r"Euler's theorem: if $\gcd(a,n)=1$, then $a^{\phi(n)}\equiv 1\pmod{n}$. Fermat is the case $n=p$. Exponent reduction: $a^k\equiv a^{k\bmod\phi(n)}\pmod{n}$ when $\gcd(a,n)=1$. Need coprimality; $2^{\phi(8)}\not\equiv 1\pmod{8}$ because $\gcd(2,8)\neq 1$.",
      r"Compute $5^{23}\bmod 12$.",
      r"$\gcd(5,12)=1$, $\phi(12)=4$, $23\equiv 3\pmod{4}$, so $5^{23}\equiv 5^3=125\equiv 5\pmod{12}$ (since $120=10\cdot 12$).",
      r"$3^4\bmod 10$", r"$\phi(10)=4$, $\gcd(3,10)=1$, so $3^4\equiv 1\pmod{10}$. Check: $81\equiv 1$.",
      r"Reducing the exponent mod $\phi(n)$ when $\gcd(a,n)>1$.",
      r"$7^{21}\bmod 10$.", r"$\phi(10)=4$, $21\equiv 1\pmod{4}$, $7^{21}\equiv 7$.",
      r"$2^4\bmod 8$ versus Euler?", r"$2^4=16\equiv 0\not\equiv 1$; Euler does not apply.")
    a(520, r"The multiplicative order $\mathrm{ord}_n(a)$ of $a$ coprime to $n$ is the least positive $k$ with $a^k\equiv 1\pmod{n}$. It divides $\phi(n)$ (Lagrange in $(\mathbb{Z}/n\mathbb{Z})^\times$). $a^m\equiv 1$ iff $\mathrm{ord}_n(a)\mid m$. $a^i\equiv a^j$ iff $\mathrm{ord}\mid(i-j)$.",
      r"Find $\mathrm{ord}_9(2)$.",
      r"$\gcd(2,9)=1$, $\phi(9)=6$ so order divides $6$. $2^1=2$, $2^2=4$, $2^3=8\equiv -1$, $2^6\equiv 1$. Least positive is $6$.",
      r"Order of $3$ mod $7$", r"$6$: $3,2,6,4,5,1$. A primitive root.",
      r"Calling the order $n$ (the modulus) rather than a divisor of $\phi(n)$.",
      r"Order of $4$ mod $7$.", r"$4^1=4$, $4^2=2$, $4^3=1\pmod{7}$, order $3$.",
      r"If $a^6\equiv 1\pmod{n}$ and $a^2\not\equiv 1$, $a^3\not\equiv 1$, the order is", r"$6$ (divisors of $6$ are $1,2,3,6$).")
    a(521, r"The group of units modulo $n$ is $(\mathbb{Z}/n\mathbb{Z})^\times=\{[a]:\gcd(a,n)=1\}$ under multiplication mod $n$. It has order $\phi(n)$. $[a][b]=[1]$ iff $b\equiv a^{-1}$. Wilson: $(p-1)!\equiv -1\pmod{p}$ for $p$ prime, because the units pair as inverses except $\pm 1$.",
      r"List $(\mathbb{Z}/8\mathbb{Z})^\times$ and its multiplication table's identity.",
      r"$\{1,3,5,7\}$. Each squares to $1\bmod 8$: Klein four-group, not cyclic.",
      r"$(\mathbb{Z}/7\mathbb{Z})^\times$ has order", r"$6$, cyclic generated by $3$.",
      r"Including residue $0$ when $n>1$, or thinking every nonzero class is a unit when $n$ is composite.",
      r"Units mod $15$.", r"$1,2,4,7,8,11,13,14$ ($\phi(15)=8$).",
      r"Inverse of $7$ in $(\mathbb{Z}/15\mathbb{Z})^\times$.", r"$13$, because $91=6\cdot 15+1$.")
    a(522, r"From $n=\prod p_i^{e_i}$, $\phi(n)=n\prod_{p\mid n}(1-1/p)=\prod p_i^{e_i-1}(p_i-1)$. In particular $\phi(2^k)=2^{k-1}$ for $k\ge 1$, and $\phi(pq)=(p-1)(q-1)$ for distinct primes. Never use $\phi(n)=n-1$ unless $n$ is prime.",
      r"Compute $\phi(360)$ from $360=2^3\cdot 3^2\cdot 5$.",
      r"$\phi(360)=360\cdot\frac12\cdot\frac23\cdot\frac45=96$. Or $2^2(1)\cdot 3(2)\cdot 4=4\cdot 6\cdot 4=96$.",
      r"$\phi(100)$ for $100=2^2 5^2$", r"$100\cdot\frac12\cdot\frac45=40$.",
      r"Writing $\phi(p^k)=p^k-1$, or $\phi(pq)=\phi(p)\phi(q)$ when $p=q$.",
      r"$\phi(p^3)$ for $p=5$.", r"$5^3-5^2=100$.",
      r"$\phi(18)$.", r"$18=2\cdot 3^2$, $\phi=18\cdot\frac12\cdot\frac23=6$.")

    # L Diophantine
    a(523, r"The linear Diophantine equation $ax+by=c$ has integer solutions iff $d=\gcd(a,b)$ divides $c$. A particular solution comes from Bézout scaled by $c/d$. Geometric view: the line meets the integer lattice iff $d\mid c$.",
      r"Does $8x+12y=20$ have integer solutions? Find one.",
      r"$d=4\mid 20$. Divide by $4$: $2x+3y=5$. One solution $x=1$, $y=1$. Then $8(1)+12(1)=20$.",
      r"$9x+6y=8$ over $\mathbb{Z}$", r"Impossible: $3\nmid 8$.",
      r"Finding a particular solution over $\mathbb{Q}$ and reporting it as an integer solution.",
      r"$10x+15y=5$: a solution.", r"$x=2$, $y=-1$, or $x=-1$, $y=1$.",
      r"Frobenius coin problem for coprime $a,b$: largest impossible is", r"$ab-a-b$. For $4,7$: $17$.")
    a(524, r"If $x_0,y_0$ is one integer solution of $ax+by=c$ and $d=\gcd(a,b)$, the general solution is $x=x_0+(b/d)t$, $y=y_0-(a/d)t$ for $t\in\mathbb{Z}$. (Signs: the combination $a(b/d)+b(-a/d)=0$.) Restrict $t$ to get positive solutions.",
      r"General integer solution of $4x+6y=2$.",
      r"$d=2\mid 2$. Divide: $2x+3y=1$. Particular $(-1,1)$. General of original: $x=-1+(6/2)t=-1+3t$, $y=1-(4/2)t=1-2t$. Check: $4(-1+3t)+6(1-2t)=-4+12t+6-12t=2$.",
      r"If $x=2+5t$, $y=-1-3t$ solves $3x+5y=1$, a particular point is", r"$(2,-1)$ at $t=0$; also $(7,-4)$ at $t=1$.",
      r"Adding $b$ to $x$ and $a$ to $y$ (same sign) — that does not stay on $ax+by=c$.",
      r"General solution of $6x+9y=3$ given particular $(2,-1)$.", r"$x=2+3t$, $y=-1-2t$ because $b/d=3$, $a/d=2$.",
      r"Positive solutions of $2x+3y=11$.", r"$x=4,y=1$ and $x=1,y=3$ (from $(4,1)$ with step $(3,-2)$).")
    a(525, r"A modular obstruction shows an equation has no integer (or rational) solutions: if a congruence implied by the equation is impossible, so is the original. Typical: squares are $0,1\bmod 4$ never $3$; cubes $0,\pm 1\bmod 9$; $ax+by=c$ fails if $\gcd(a,b)\nmid c$. Working modulo a well-chosen $n$ is the GRE default obstruction.",
      r"Show $x^2+y^2=4k+3$ has no integer solutions.",
      r"Squares $\bmod 4$ are $0$ or $1$, so sums are $0,1,2$, never $3\bmod 4$.",
      r"$15x+25y=7$ over $\mathbb{Z}$", r"Impossible: $\gcd=5\nmid 7$. Equivalently $0\equiv 2\pmod{5}$.",
      r"Checking only modulo $2$ when the obstruction lives at $4$ or $8$ (e.g. $x^2\equiv 7\pmod{8}$ is already impossible).",
      r"Can $n^2\equiv 2\pmod{4}$?", r"No.",
      r"Is $x^2-5y^2=2$ possible mod $5$?", r"$x^2\equiv 2\pmod{5}$. Squares mod $5$ are $0,1,4$. No.")
    a(526, r"A Pythagorean triple is $a,b,c>0$ with $a^2+b^2=c^2$. Primitive triples (gcd $1$, not both legs even) are $a=m^2-n^2$, $b=2mn$, $c=m^2+n^2$ (or $a\leftrightarrow b$) for integers $m>n>0$ of opposite parity and $\gcd(m,n)=1$. All triples are integer multiples of primitives.",
      r"Generate the triple for $m=2$, $n=1$, and a nonprimitive relative.",
      r"$m^2-n^2=3$, $2mn=4$, $m^2+n^2=5$. Multiple: $6,8,10$.",
      r"$m=3$, $n=2$ gives", r"$5,12,13$.",
      r"Using $m,n$ both odd: $m=3,n=1$ gives $8,6,10=2(3,4,5)$, not primitive (both legs even).",
      r"Is $(9,12,15)$ primitive?", r"No: $\gcd=3$.",
      r"Smallest primitive triple with hypotenuse $25$.", r"$7,24,25$ ($m=4,n=3$: $16-9=7$, $24$, $16+9=25$).")
    a(527, r"Integer-factorization arguments: rewrite a Diophantine equation so both sides factor, then use that $\mathbb{Z}$ is a UFD. Typical: $x^2-y^2=(x-y)(x+y)$, $n^2-1=(n-1)(n+1)$, $xy=n$ with $x\le y$ enumerates divisor pairs. Equal-factor constraints plus parity/gcd finish the list.",
      r"Find all positive $x>y>0$ of the same parity with $x^2-y^2=15$.",
      r"$15=(x-y)(x+y)$. Factor pairs of the same parity: $(1,15)$, $(3,5)$ (both odd). $x-y=1$, $x+y=15\Rightarrow x=8,y=7$. And $x-y=3$, $x+y=5\Rightarrow x=4,y=1$.",
      r"Positive pairs $(x,y)$ with $xy=12$, $x\le y$", r"$(1,12),(2,6),(3,4)$.",
      r"Forgetting that $x-y$ and $x+y$ must both be even or both odd (same parity as $2x,2y$).",
      r"Integer solutions of $x(x+1)=6$.", r"$x=2$ and $x=-3$ (because $(-3)(-2)=6$).",
      r"Positive $m$ with $m(m+2)=24$.", r"$m=4$: factors of $24$ differing by $2$ are $4$ and $6$.")
    a(528, r"The Pell equation $x^2-dy^2=1$ for squarefree $d>0$ has infinitely many integer solutions generated from a fundamental solution $(x_1,y_1)$ by $x_k+y_k\sqrt{d}=(x_1+y_1\sqrt{d})^k$. The related $x^2-dy^2=\pm 1,\pm 4$ appear as units in $\mathbb{Z}[\sqrt{d}]$. GRE needs recognition and small-solution search, not the full theory.",
      r"Find the fundamental solution of $x^2-2y^2=1$ and the next solution.",
      r"$(x,y)=(3,2)$ because $9-8=1$ (besides the trivial $(1,0)$). Next: $(3+2\sqrt{2})^2=17+12\sqrt{2}$, so $(17,12)$: $289-2\cdot 144=289-288=1$.",
      r"$x^2-3y^2=1$ fundamental positive solution", r"$(2,1)$: $4-3=1$.",
      r"Searching only for $x^2-dy^2=0$ (that would force $\sqrt{d}$ rational) or assuming no nontrivial solution (Pell always has one).",
      r"A solution of $x^2-5y^2=-1$.", r"$(2,1)$: $4-5=-1$.",
      r"If $x^2-dy^2=1$ and $d=k^2$, extra solutions besides $(\pm 1,0)$?", r"No: $x^2-k^2 y^2=1$ is $(x-ky)(x+ky)=1$, only $\pm 1$.")

    # L extra elementary NT
    a(529, r"An integer $a$ is a quadratic residue mod $n$ if $\gcd(a,n)=1$ and $x^2\equiv a\pmod{n}$ is solvable (sometimes $0$ is included as a trivial residue). Mod an odd prime $p$ there are $(p-1)/2$ nonzero residues and $(p-1)/2$ nonresidues. The residues are the distinct values of $1^2,2^2,\ldots,((p-1)/2)^2\bmod p$.",
      r"Find the quadratic residues modulo $7$.",
      r"$1^2\equiv 1$, $2^2\equiv 4$, $3^2\equiv 2$, $4^2\equiv 2$, $5^2\equiv 4$, $6^2\equiv 1$. Nonzero residues: $1,2,4$. Nonresidues: $3,5,6$.",
      r"Is $3$ a quadratic residue mod $11$?", r"$1^2=1$, $2^2=4$, $3^2=9$, $4^2=5$, $5^2=3$. Yes, $5^2\equiv 3$.",
      r"Testing only $x=1,2$ and declaring a nonresidue, or including $0$ when the problem said coprime residues.",
      r"Squares modulo $8$ among odd units.", r"Odd squares are $1\bmod 8$ only.",
      r"Number of solutions of $x^2\equiv 1\pmod{8}$.", r"Four: $1,3,5,7$ all square to $1$.")
    a(530, r"The Legendre symbol $\bigl(\frac{a}{p}\bigr)$ for odd prime $p$ is $0$ if $p\mid a$, $+1$ if $a$ is a nonzero quadratic residue mod $p$, and $-1$ if a nonresidue. Euler's criterion: $\bigl(\frac{a}{p}\bigr)\equiv a^{(p-1)/2}\pmod{p}$. Completely multiplicative in $a$: $\bigl(\frac{ab}{p}\bigr)=\bigl(\frac{a}{p}\bigr)\bigl(\frac{b}{p}\bigr)$. $\bigl(\frac{-1}{p}\bigr)=(-1)^{(p-1)/2}$, $\bigl(\frac{2}{p}\bigr)=(-1)^{(p^2-1)/8}$.",
      r"Compute $\bigl(\frac{3}{7}\bigr)$ by listing and by Euler.",
      r"Residues mod $7$ are $1,2,4$, so $3$ is a nonresidue: $-1$. Euler: $3^3=27\equiv 6\equiv -1\pmod{7}$.",
      r"$\bigl(\frac{-1}{13}\bigr)$ equals", r"$1$ because $13\equiv 1\pmod{4}$. (For $p\equiv 3\pmod{4}$ it is $-1$.)",
      r"Using $\bigl(\frac{a}{p}\bigr)=a\bmod p$, or applying Legendre at a composite ‘prime’.",
      r"$\bigl(\frac{2}{7}\bigr)$.", r"$7\equiv -1\pmod{8}$, so $+1$ (the symbol is $-1$ iff $p\equiv\pm 3\pmod{8}$). Check: $3^2=9\equiv 2\pmod{7}$.",
      r"$\bigl(\frac{5}{11}\bigr)$ by Euler: $5^5\bmod 11$.", r"$5^2=3$, $5^4=9$, $5^5=45\equiv 1\pmod{11}$, so $+1$.")
    a(531, r"Quadratic reciprocity: for distinct odd primes $p,q$, $\bigl(\frac{p}{q}\bigr)\bigl(\frac{q}{p}\bigr)=(-1)^{(p-1)(q-1)/4}$. The exponent is odd iff both primes are $3\bmod 4$, in which case the symbols are opposite; otherwise they agree. Combined with the supplementary laws for $-1$ and $2$, this computes Legendre symbols by descent.",
      r"Compute $\bigl(\frac{5}{13}\bigr)$ by reciprocity.",
      r"Both $1\bmod 4$, so $\bigl(\frac{5}{13}\bigr)=\bigl(\frac{13}{5}\bigr)=\bigl(\frac{3}{5}\bigr)$. Now $5\equiv 1\bmod 4$, $\bigl(\frac{3}{5}\bigr)=\bigl(\frac{5}{3}\bigr)=\bigl(\frac{2}{3}\bigr)$. $3\equiv 3\pmod{8}$, $\bigl(\frac{2}{3}\bigr)=-1$. So $\bigl(\frac{5}{13}\bigr)=-1$.",
      r"$\bigl(\frac{3}{7}\bigr)\bigl(\frac{7}{3}\bigr)$ equals", r"$-1$, because both primes are $3\bmod 4$. And $\bigl(\frac{7}{3}\bigr)=\bigl(\frac{1}{3}\bigr)=1$, so $\bigl(\frac{3}{7}\bigr)=-1$.",
      r"Flipping symbols when one prime is $1\bmod 4$ (no sign change then).",
      r"Does $\bigl(\frac{7}{11}\bigr)=\bigl(\frac{11}{7}\bigr)$?", r"No: both $3\bmod 4$, they are opposite. $\bigl(\frac{11}{7}\bigr)=\bigl(\frac{4}{7}\bigr)=1$, so $\bigl(\frac{7}{11}\bigr)=-1$.",
      r"Evaluate $\bigl(\frac{13}{17}\bigr)$.", r"Both $1\bmod 4$: $=\bigl(\frac{17}{13}\bigr)=\bigl(\frac{4}{13}\bigr)=1$.")
    a(532, r"A primitive root modulo $n$ is a generator of $(\mathbb{Z}/n\mathbb{Z})^\times$, i.e. an $a$ with $\mathrm{ord}_n(a)=\phi(n)$. Primitive roots exist iff $n=2,4,p^k,2p^k$ for odd prime $p$. There are $\phi(\phi(n))$ of them when they exist. To test: $a^{\phi(n)/q}\not\equiv 1\pmod{n}$ for every prime $q\mid\phi(n)$.",
      r"Show $3$ is a primitive root mod $7$. How many primitive roots mod $7$?",
      r"$\phi(7)=6=2\cdot 3$. $3^2=2\not\equiv 1$, $3^3=27\equiv 6\not\equiv 1\pmod{7}$. Order $6$. Number: $\phi(6)=2$, namely $3$ and $3^5\equiv 5\pmod{7}$ (the $k$ coprime to $6$).",
      r"Does $8$ have a primitive root?", r"No: $(\mathbb{Z}/8\mathbb{Z})^\times$ is Klein, not cyclic.",
      r"Testing only $a^{n-1}\not\equiv 1$ (wrong exponent; need $\phi(n)$ and its prime divisors).",
      r"Is $2$ a primitive root mod $9$?", r"$\phi(9)=6$. $2^1=2$, $2^2=4$, $2^3=-1$, $2^6=1$, order $6$: yes.",
      r"Primitive roots mod $5$.", r"$2$ and $3$: $2,4,3,1$ and $3,4,2,1$.")
    a(533, r"The Möbius function: $\mu(1)=1$; $\mu(n)=0$ if $p^2\mid n$ for some prime $p$; $\mu(n)=(-1)^k$ if $n$ is a product of $k$ distinct primes. $\mu$ is multiplicative. $\sum_{d\mid n}\mu(d)=1$ if $n=1$ and $0$ otherwise (characteristic of $\{1\}$).",
      r"Evaluate $\mu(1),\mu(6),\mu(12),\mu(30)$.",
      r"$\mu(1)=1$. $6=2\cdot 3$, $\mu=1$. $12=2^2\cdot 3$, $\mu=0$. $30=2\cdot 3\cdot 5$, $\mu=-1$.",
      r"$\mu(p^k)$ for $k\ge 2$", r"$0$. For $k=1$, $\mu(p)=-1$.",
      r"Using $\mu(n)=(-1)^{\omega(n)}$ even when $n$ is not squarefree.",
      r"$\mu(15)$.", r"$15=3\cdot 5$, two primes, $+1$.",
      r"$\sum_{d\mid 6}\mu(d)$.", r"$\mu(1)+\mu(2)+\mu(3)+\mu(6)=1-1-1+1=0$.")
    a(534, r"Möbius inversion: if $g(n)=\sum_{d\mid n}f(d)$ for all $n$, then $f(n)=\sum_{d\mid n}\mu(d)g(n/d)=\sum_{d\mid n}\mu(n/d)g(d)$. Classic: $n=\sum_{d\mid n}\phi(d)$ inverts to $\phi(n)=\sum_{d\mid n}\mu(d)\,n/d$. The Dirichlet convolution identity is $f=g*\mu$ when $g=f*1$.",
      r"Recover $\phi(10)$ from $n=\sum_{d\mid n}\phi(d)$ by inversion.",
      r"$\phi(10)=\sum_{d\mid 10}\mu(d)\cdot 10/d=\mu(1)10+\mu(2)5+\mu(5)2+\mu(10)1=10-5-2+1=4$.",
      r"If $g(n)=\sum_{d\mid n}f(d)$ and $g=u$ (unit: $u(1)=1$, else $0$), then $f=$", r"$\mu$.",
      r"Summing $f(d)g(n/d)$ without the $\mu$ factor, or inverting only over primes.",
      r"Invert $d(n)=\sum_{d\mid n}1$ to get $1$ at $n=1$ and $0$ else: the formula is", r"$\sum_{d\mid n}\mu(d)$, which is $0$ for $n>1$.",
      r"Write $\phi(p^k)$ by inversion.", r"$\mu(1)p^k+\mu(p)p^{k-1}=p^k-p^{k-1}$.")
    a(535, r"An arithmetic function $f$ is multiplicative if $\gcd(m,n)=1\Rightarrow f(mn)=f(m)f(n)$, and completely multiplicative if this holds for all $m,n$. Multiplicative functions are determined by their values at prime powers. $d,\sigma,\phi,\mu$ are multiplicative; $d$ and $\phi$ are not completely multiplicative. Dirichlet convolution preserves multiplicativity.",
      r"Check $\sigma(12)=\sigma(4)\sigma(3)$ and compare $\sigma(16)$ vs $\sigma(4)^2$.",
      r"$\sigma(4)=1+2+4=7$, $\sigma(3)=4$, product $28=\sigma(12)$. Completely? $\sigma(16)=1+2+4+8+16=31$, $\sigma(4)^2=49\neq 31$.",
      r"Is $\phi$ completely multiplicative?", r"No: $\phi(4)=2$, $\phi(2)^2=1$.",
      r"Using $f(p^k)=f(p)^k$ for a merely multiplicative $f$ (that is the complete case).",
      r"If $f$ is multiplicative and $n=p^a q^b$, then $f(n)=$", r"$f(p^a)f(q^b)$.",
      r"Is $\mu$ completely multiplicative?", r"No: $\mu(4)=0$, $\mu(2)\mu(2)=1$.")
    a(536, r"A (simple) continued fraction $[a_0;a_1,a_2,\ldots]$ with $a_i\in\mathbb{Z}$, $a_i>0$ for $i\ge 1$, equals $a_0+1/(a_1+1/(a_2+\cdots))$. Finite CFs are rational; infinite CFs are irrational. Quadratic irrationals have eventually periodic CFs. Convergents $p_k/q_k$ are best approximations: $|x-p/q|<1/(2q^2)$ implies $p/q$ is a convergent.",
      r"Expand $13/8$ as a continued fraction, and recall $\sqrt{2}$.",
      r"$13/8=1+5/8=1+1/(8/5)=1+1/(1+3/5)=1+1/(1+1/(5/3))=1+1/(1+1/(1+2/3))=[1;1,1,1,2]$. $\sqrt{2}=[1;\overline{2}]$.",
      r"The first two convergents of $\sqrt{2}=[1;2,2,\ldots]$", r"$1/1$ and $3/2$ ($1+1/2$), then $7/5$, $17/12$.",
      r"Allowing $a_i=0$ in the tail (that just shortens the CF) or thinking every irrational has a finite CF.",
      r"$22/7$ as a CF.", r"$22/7=3+1/7=[3;7]$, the famous $\pi$ convergent.",
      r"Convergent $p_1/q_1$ of $[a_0;a_1]$.", r"$(a_0 a_1+1)/a_1$.")
    a(537, r"The $p$-adic valuation $v_p(n)$ for prime $p$ is the largest $e$ with $p^e\mid n$ (and $v_p(0)=\infty$). Then $v_p(ab)=v_p(a)+v_p(b)$ and $v_p(a+b)\ge\min(v_p(a),v_p(b))$, with equality if the mins differ. de Polignac / Legendre: $v_p(n!)=\sum_{k\ge 1}\lfloor n/p^k\rfloor$.",
      r"Compute $v_2(48)$ and $v_5(10!)$.",
      r"$48=16\cdot 3=2^4\cdot 3$, so $v_2=4$. $v_5(10!)=\lfloor 10/5\rfloor=2$ (the factors $5$ and $10$).",
      r"$v_3(1000)$ equals", r"$0$: $1000=2^3 5^3$.",
      r"Writing $v_p(a+b)=v_p(a)+v_p(b)$, or stopping Legendre at $\lfloor n/p\rfloor$ when $n\ge p^2$.",
      r"$v_2(64)$.", r"$6$.",
      r"Trailing zeros of $25!$ in base $10$.", r"$\min(v_2,v_5)=v_5(25!)=\lfloor 25/5\rfloor+\lfloor 25/25\rfloor=5+1=6$.")

    # M groups
    a(538, r"A binary operation on a set $S$ is a map $S\times S\to S$ (closure). Examples: $+,\cdot$ on $\mathbb{Z}$; composition of functions; matrix multiplication on $M_n$. It may or may not be associative ($(ab)c=a(bc)$) or commutative ($ab=ba$). Subtraction on $\mathbb{Z}$ is binary but not associative; division is not even a binary operation on $\mathbb{Z}$.",
      r"Is subtraction on $\mathbb{Z}$ associative? Is matrix multiplication on $M_2(\mathbb{R})$ commutative?",
      r"$(1-2)-3=-4$ but $1-(2-3)=2$, not associative. Matrix multiplication is associative but not commutative: $\begin{pmatrix}0&1\\0&0\end{pmatrix}\begin{pmatrix}0&0\\1&0\end{pmatrix}\neq$ the swap.",
      r"Is $a*b=(a+b)/2$ a binary operation on $\mathbb{Z}$?", r"No: not closed ($1*2=1.5\notin\mathbb{Z}$).",
      r"Forgetting closure (max on $\mathbb{Q}$ is fine; geometric mean on $\mathbb{R}$ fails negatives).",
      r"Is union a binary operation on the power set of $\{1,2,3\}$?", r"Yes, associative and commutative.",
      r"Exponentiation $a*b=a^b$ on $\mathbb{Z}_{>0}$: associative?", r"No: $(2^3)^2=64$, $2^{(3^2)}=512$.")
    a(539, r"A group is a set $G$ with an associative binary operation, an identity $e$ with $eg=ge=g$, and inverses $g^{-1}$ with $gg^{-1}=g^{-1}g=e$. (Some texts list closure separately.) Cancellation holds: $ab=ac\Rightarrow b=c$. Examples: $(\mathbb{Z},+)$, $(\mathbb{R}^\times,\cdot)$, $GL_n(F)$, $S_n$. Nonexamples: $(\mathbb{N},+)$, $(\mathbb{R},\cdot)$.",
      r"Which of $(\mathbb{Z},+)$, $(\mathbb{N},+)$, $(\mathbb{R}\setminus\{0\},\cdot)$, $(\mathbb{R},\cdot)$ are groups?",
      r"$(\mathbb{Z},+)$ yes. $(\mathbb{N},+)$ no inverses. $(\mathbb{R}\setminus\{0\},\cdot)$ yes. $(\mathbb{R},\cdot)$ no: $0$ has no inverse.",
      r"The identity in $GL_2(\mathbb{R})$ is", r"the identity matrix $I_2$.",
      r"Checking inverses but not associativity (or vice versa); or requiring commutativity as an axiom.",
      r"Is $\{1,-1\}$ under multiplication a group?", r"Yes: cyclic of order $2$.",
      r"Does every group satisfy $(ab)^{-1}=a^{-1}b^{-1}$?", r"No: $(ab)^{-1}=b^{-1}a^{-1}$.")
    a(540, r"A group is abelian (commutative) if $ab=ba$ for all $a,b$. Additive notation is common then. All cyclic groups are abelian. $(\mathbb{Z},+)$, $(\mathbb{Z}/n\mathbb{Z},+)$, and $(\mathbb{R}^\times,\cdot)$ are abelian; $S_n$ for $n\ge 3$ and $GL_n(F)$ for $n\ge 2$ are not. In an abelian group, $(ab)^{-1}=a^{-1}b^{-1}$ coincides with $b^{-1}a^{-1}$.",
      r"Is $S_3$ abelian? Is $\mathbb{Z}/6\mathbb{Z}$ abelian?",
      r"$S_3$: $(1\,2)(1\,3)\neq(1\,3)(1\,2)$, not abelian. $\mathbb{Z}/6\mathbb{Z}$ is cyclic, hence abelian.",
      r"A nonabelian group of smallest order", r"$S_3$ (order $6$). Order $4$ groups are abelian.",
      r"Assuming $GL_2(\mathbb{R})$ is abelian because $\mathbb{R}$ is.",
      r"Is every subgroup of an abelian group abelian?", r"Yes.",
      r"Name an infinite nonabelian group.", r"$GL_2(\mathbb{R})$, or $S_{\mathbb{Z}}$, or invertible $2\times 2$ integer matrices $GL_2(\mathbb{Z})$.")
    a(541, r"The identity is unique: if $e,e'$ both act as identities then $e=ee'=e'$. The inverse of $g$ is unique, and $(g^{-1})^{-1}=g$, $(ab)^{-1}=b^{-1}a^{-1}$. Left identity plus left inverses already imply a group (a common shortcut). Solving $ax=b$ gives $x=a^{-1}b$.",
      r"Prove the identity is unique, and compute $(2\,3)^{-1}$ in $S_3$.",
      r"If $eg=g=e'g$ then $e=e(e')=(ee')=e'$. A transposition is its own inverse: $(2\,3)^{-1}=(2\,3)$.",
      r"$(ab)^{-1}$ equals", r"$b^{-1}a^{-1}$, not $a^{-1}b^{-1}$ in general.",
      r"Canceling ‘the identity’ of two different operations (e.g. $0$ vs $1$).",
      r"Inverse of $3$ in $(\mathbb{Z}/10\mathbb{Z})^\times$.", r"$7$.",
      r"If $g^2=e$, then $g^{-1}=$", r"$g$.")
    a(542, r"A subset $H\subseteq G$ is a subgroup if it is a group under the restricted operation. Then $e\in H$ and $H$ is closed under products and inverses. Notation $H\le G$. Examples: $n\mathbb{Z}\le\mathbb{Z}$, $SL_n\le GL_n$, $\{e\}\le G$ and $G\le G$ (trivial and improper). Intersection of subgroups is a subgroup.",
      r"Is $\{0,2,4\}$ a subgroup of $\mathbb{Z}/6\mathbb{Z}$? Is the odd integers a subgroup of $\mathbb{Z}$?",
      r"Yes: closed, identity $0$, inverses ($2+4=0$). Odds: no, $1+1=2$ even, not closed, and $0$ is even.",
      r"$2\mathbb{Z}\cap 3\mathbb{Z}$ equals", r"$6\mathbb{Z}$.",
      r"Checking closure under the operation but not inverses in an infinite set (e.g. $\mathbb{N}$ in $\mathbb{Z}$).",
      r"Is $SO(2)$ a subgroup of $GL_2(\mathbb{R})$?", r"Yes: rotations, closed, inverses are opposite rotations.",
      r"Does $H\cup K$ have to be a subgroup if $H,K$ are?", r"No, unless one contains the other.")
    a(543, r"One-step subgroup test: a nonempty $H\subseteq G$ is a subgroup iff $a,b\in H\Rightarrow ab^{-1}\in H$. Two-step: closed under the operation and under inverses. Finite case: a nonempty finite subset closed under the operation is a subgroup (inverses come from $a^{k}=e$ in the powers). The subgroup generated by a subset is the smallest subgroup containing it.",
      r"Show that $H=\{A\in GL_n(\mathbb{R}):\det A=\pm 1\}$ is a subgroup by the one-step test.",
      r"Nonempty ($I$). If $\det A,\det B=\pm 1$, then $\det(AB^{-1})=(\det A)(\det B)^{-1}=\pm 1$.",
      r"Is $\mathbb{Z}_{>0}$ a subgroup of $(\mathbb{Q}^\times,\cdot)$?", r"No: $2\cdot 3^{-1}=2/3\notin\mathbb{Z}_{>0}$.",
      r"Using the finite-closure test on an infinite set (positive reals under addition fail inverses).",
      r"Positive even integers under addition: subgroup of $\mathbb{Z}$?", r"No: no identity $0$, no inverses.",
      r"Finite closed nonempty subset of $S_3$: $\{e,(1\,2\,3),(1\,3\,2)\}$. Subgroup?", r"Yes, $A_3$.")
    a(544, r"A group is cyclic if $G=\langle g\rangle=\{g^k:k\in\mathbb{Z}\}$ for some $g$ (additive: multiples). Finite cyclic of order $n$ is isomorphic to $\mathbb{Z}/n\mathbb{Z}$; infinite cyclic to $\mathbb{Z}$. Cyclic groups are abelian. $G$ cyclic of order $n$ iff it has an element of order $n$. $U(n)=(\mathbb{Z}/n\mathbb{Z})^\times$ is cyclic iff $n=2,4,p^k,2p^k$.",
      r"Is $\mathbb{Z}/8\mathbb{Z}$ cyclic? Is $(\mathbb{Z}/8\mathbb{Z})^\times$ cyclic?",
      r"Yes: generated by $[1]$ (or $[3],[5],[7]$). Units $\{1,3,5,7\}$ all have order dividing $2$, so Klein, not cyclic.",
      r"Every group of prime order is", r"cyclic (Lagrange: any non-identity element generates).",
      r"Concluding a group is cyclic from being abelian (Klein counterexample).",
      r"Generator of $(\mathbb{Z},+)$ besides $1$.", r"$-1$ only.",
      r"Is $S_3$ cyclic?", r"No: not even abelian; max element order $3$, group order $6$.")
    a(545, r"An element $g$ generates $G$ if $\langle g\rangle=G$. For $\mathbb{Z}/n\mathbb{Z}$, $[k]$ generates iff $\gcd(k,n)=1$; there are $\phi(n)$ generators. For $\langle g\rangle$ of order $n$, $g^k$ generates iff $\gcd(k,n)=1$. Powers: $\langle g^k\rangle$ has order $n/\gcd(k,n)$.",
      r"List the generators of $\mathbb{Z}/12\mathbb{Z}$.",
      r"$[1],[5],[7],[11]$: the units mod $12$. Check: $\langle 5\rangle=\{0,5,10,3,8,1,\ldots\}$ fills all.",
      r"Number of generators of a cyclic group of order $10$", r"$\phi(10)=4$.",
      r"Thinking $2$ generates $\mathbb{Z}/8\mathbb{Z}$ (order of $2$ is $4$, not $8$).",
      r"Does $3$ generate $(\mathbb{Z}/7\mathbb{Z})^\times$?", r"Yes: it is a primitive root.",
      r"Order of $g^2$ if $|g|=12$.", r"$12/\gcd(2,12)=6$.")
    a(546, r"The order of $g\in G$ is $|g|=\mathrm{ord}(g)$, the least positive integer $k$ with $g^k=e$ (or $\infty$). In additive groups, least $k>0$ with $kg=0$. Then $g^m=e$ iff $\mathrm{ord}(g)\mid m$. In a finite group every order is finite. $\mathrm{ord}(g^{-1})=\mathrm{ord}(g)$, and $\mathrm{ord}(hgh^{-1})=\mathrm{ord}(g)$.",
      r"Order of $[4]$ in $\mathbb{Z}/12\mathbb{Z}$, and of $2$ in $(\mathbb{Z}/7\mathbb{Z})^\times$.",
      r"$4+4+4=12\equiv 0$, order $3$. $2^1=2$, $2^2=4$, $2^3=1\pmod{7}$, order $3$.",
      r"Order of a $k$-cycle in $S_n$", r"$k$. Order of a product of disjoint cycles is the lcm of their lengths.",
      r"Confusing $|g|$ with $|G|$, or thinking $g^{|G|}=e$ implies $\mathrm{ord}(g)=|G|$.",
      r"Order of $(1\,2)(3\,4\,5)$ in $S_5$.", r"$\mathrm{lcm}(2,3)=6$.",
      r"If $g^6=e$ and $g^2\neq e$, $g^3\neq e$, then $\mathrm{ord}(g)=$", r"$6$.")
    a(547, r"The order of a finite group is $|G|$, the number of elements. $|H|$ divides $|G|$ for $H\le G$ (Lagrange). $|G\times K|=|G|\,|K|$. $|S_n|=n!$, $|A_n|=n!/2$ for $n\ge 2$, $|GL_2(\mathbb{F}_p)|=(p^2-1)(p^2-p)$. The exponent of $G$ is $\mathrm{lcm}$ of element orders, dividing $|G|$ if $G$ is finite.",
      r"Compute $|S_4|$ and $|A_4|$.",
      r"$24$ and $12$.",
      r"$|\mathbb{Z}/n\mathbb{Z}|$ equals", r"$n$. $|(\mathbb{Z}/n\mathbb{Z})^\times|=\phi(n)$.",
      r"Using $|GL_n(\mathbb{R})|=\infty$ as if it were $n!$, or writing $|A_n|=n!$.",
      r"$|D_4|$ (symmetries of the square).", r"$8$: $4$ rotations, $4$ reflections.",
      r"$|GL_2(\mathbb{F}_2)|$.", r"$(4-1)(4-2)=6$, isomorphic to $S_3$.")
    a(548, r"A finite group has finitely many elements. Classification crumbs: order $p$ prime $\Rightarrow$ cyclic; order $p^2\Rightarrow$ abelian ($\mathbb{Z}/p^2$ or $\mathbb{Z}/p\times\mathbb{Z}/p$); order $pq$ with $p<q$ primes, $p\nmid q-1\Rightarrow$ cyclic. $S_3$, $D_4$, $Q_8$, $A_4$ are the GRE stock nonabelian examples. Cayley: every finite $G$ embeds in $S_{|G|}$.",
      r"Up to isomorphism, the groups of order $4$.",
      r"$\mathbb{Z}/4\mathbb{Z}$ and $\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/2\mathbb{Z}$ (Klein). Both abelian.",
      r"A nonabelian group of order $8$", r"$D_4$ or $Q_8$.",
      r"Claiming there is a unique group of each order (false from order $4$ on, except primes).",
      r"Groups of order $6$ up to iso.", r"$\mathbb{Z}/6\mathbb{Z}$ and $S_3$.",
      r"Is every finite abelian group cyclic?", r"No: Klein four.")

    # M permutations
    a(549, r"A permutation of a set $X$ is a bijection $X\to X$. The set $S_X$ of permutations is a group under composition (the symmetric group). For $X=\{1,\ldots,n\}$, write $S_n$. $|S_n|=n!$. The identity permutation fixes every point. Two-row notation lists images of $1,\ldots,n$.",
      r"How many permutations of $\{1,2,3,4\}$ send $1$ to $2$? Write one in two-row form.",
      r"$3!=6$ (the rest may be any permutation of the remaining three). Example: $\bigl(\begin{smallmatrix}1&2&3&4\\2&1&4&3\end{smallmatrix}\bigr)$.",
      r"A permutation is injective. Why is it then automatically surjective on a finite set?", r"Finite set, injective $\Rightarrow$ surjective.",
      r"Counting functions $\{1,\ldots,n\}\to\{1,\ldots,n\}$ as $n!$ (that is $n^n$; permutations are the bijections).",
      r"$|S_5|$.", r"$120$.",
      r"Is the map $1\mapsto 2,2\mapsto 3,3\mapsto 2$ a permutation of $\{1,2,3\}$?", r"No: not injective/surjective ($1$ has no preimage, $2$ hit twice).")
    a(550, r"Cycle notation: $(a_1\,a_2\,\ldots\,a_k)$ is the permutation sending $a_i\mapsto a_{i+1}$, $a_k\mapsto a_1$, and fixing the rest. A $k$-cycle has order $k$. Cycles are unique up to rotation: $(1\,2\,3)=(2\,3\,1)$. $(a\,b)$ is a transposition. Disjoint cycle decomposition is unique up to order of the cycles.",
      r"Write $\bigl(\begin{smallmatrix}1&2&3&4&5\\ 3&1&2&5&4\end{smallmatrix}\bigr)$ in cycle notation.",
      r"$1\mapsto 3\mapsto 2\mapsto 1$ and $4\mapsto 5\mapsto 4$, so $(1\,3\,2)(4\,5)$.",
      r"$(1\,2\,3)^{-1}$ equals", r"$(1\,3\,2)$ (reverse the cycle).",
      r"Reading $(1\,2\,3)$ as swapping $1$ with $2$ and leaving $3$ (that is a transposition times a fixed point).",
      r"Cycle type of $(1\,4\,2\,7)(3\,5)$ in $S_7$.", r"A $4$-cycle and a $2$-cycle (and a $1$-cycle $6$).",
      r"Does $(1\,2\,3)=(3\,1\,2)$?", r"Yes, rotation. Not equal to $(1\,3\,2)$.")
    a(551, r"Disjoint cycles commute: if $\sigma,\tau$ move disjoint sets, $\sigma\tau=\tau\sigma$. Every permutation is a product of disjoint cycles, unique up to ordering. The order of a product of disjoint cycles is the lcm of their lengths. Conjugacy class in $S_n$ is determined by cycle type.",
      r"Order of $(1\,2\,3)(4\,5)$ and of $(1\,2)(3\,4)$. Do they commute with each other?",
      r"$\mathrm{lcm}(3,2)=6$; $\mathrm{lcm}(2,2)=2$. The two displayed permutations are not disjoint from each other? $(1\,2\,3)(4\,5)$ and $(1\,2)(3\,4)$ share $\{1,2,3\}$ — they need not commute. Disjoint internally: $(1\,2\,3)$ commutes with $(4\,5)$.",
      r"Order of a product of disjoint cycles of lengths $4,6,5$", r"$\mathrm{lcm}(4,6,5)=60$.",
      r"Taking the product of the lengths instead of lcm, or assuming nondisjoint cycles commute.",
      r"Does $(1\,2)$ commute with $(3\,4)$?", r"Yes, disjoint.",
      r"Can a $6$-cycle equal a product of two disjoint $3$-cycles?", r"No: different cycle types; a $6$-cycle is a single orbit of size $6$.")
    a(552, r"A transposition is a $2$-cycle. Adjacent transpositions $(i\,i+1)$ generate $S_n$. Any $k$-cycle is a product of $k-1$ transpositions: $(a_1\,\ldots\,a_k)=(a_1\,a_k)\cdots(a_1\,a_2)$. The factorization into transpositions is not unique, but the parity of the number of factors is.",
      r"Write $(1\,2\,3\,4)$ as transpositions, and factor $(1\,3)$ using adjacent transpositions.",
      r"$(1\,2\,3\,4)=(1\,4)(1\,3)(1\,2)$. And $(1\,3)=(1\,2)(2\,3)(1\,2)$.",
      r"A $5$-cycle is a product of how many transpositions in the standard factorization?", r"$4$.",
      r"Thinking the transposition factorization is unique (so $(1\,2)(1\,2)(1\,3)$ would ‘change’ $(1\,3)$).",
      r"$(1\,2)(1\,2)$ equals", r"the identity (even number of transpositions).",
      r"Generate $S_3$ by $\{(1\,2),(1\,2\,3)\}$?", r"Yes: those two generate (standard presentation).")
    a(553, r"A permutation is even if it is a product of an even number of transpositions, odd otherwise. The sign $\mathrm{sgn}:S_n\to\{\pm 1\}$ is a homomorphism, kernel $A_n$. A $k$-cycle is even iff $k$ is odd (because it is $k-1$ transpositions). Sign is well-defined: you cannot write an even permutation as an odd product of transpositions.",
      r"Is $(1\,2\,3)$ even? Is $(1\,2)(3\,4\,5)$ even?",
      r"$(1\,2\,3)$ is a $3$-cycle, even. $(1\,2)$ odd times a $3$-cycle even is odd.",
      r"Sign of an $n$-cycle in $S_n$", r"$(-1)^{n-1}$.",
      r"Treating every cycle as odd, or using ‘number of cycles’ instead of ‘number of transpositions’.",
      r"Parity of $(1\,2\,3\,4\,5)(6\,7)$.", r"Even $5$-cycle times odd transposition: odd.",
      r"Can a product of $3$ transpositions equal a $3$-cycle?", r"Yes in length, but a $3$-cycle is even, $3$ transpositions odd: not equal. (A $3$-cycle is $2$ transpositions.)")
    a(554, r"$S_n$ is the symmetric group on $n$ letters, order $n!$. It is nonabelian for $n\ge 3$. It is generated by all transpositions, or by adjacent transpositions, or by $\{(1\,2),(1\,2\,\ldots\,n)\}$. $S_n$ acts faithfully on $\{1,\ldots,n\}$. For $n\ge 3$, $Z(S_n)=\{e\}$.",
      r"Show $S_3$ is nonabelian by an explicit product, and give $|S_6|$.",
      r"$(1\,2)(1\,3)=(1\,3\,2)$ while $(1\,3)(1\,2)=(1\,2\,3)$, composition $\sigma\tau$ meaning apply $\tau$ first. $|S_6|=720$.",
      r"Center of $S_4$", r"Trivial.",
      r"Thinking $S_n$ is cyclic, or $|S_n|=n$.",
      r"$S_2$ is isomorphic to", r"$\mathbb{Z}/2\mathbb{Z}$.",
      r"A generating set of $S_4$ of two elements exists?", r"Yes, e.g. $(1\,2)$ and $(1\,2\,3\,4)$.")
    a(555, r"The alternating group $A_n$ is the kernel of $\mathrm{sgn}:S_n\to\{\pm 1\}$, hence a normal subgroup of index $2$, order $n!/2$ ($n\ge 2$). It consists of the even permutations and is generated by $3$-cycles. $A_n$ is simple for $n\ge 5$. $A_4$ has a normal Klein four-group $V=\{e,(1\,2)(3\,4),(1\,3)(2\,4),(1\,4)(2\,3)\}$ and is not simple.",
      r"List $A_3$ and decide whether $A_4$ has an element of order $6$.",
      r"$A_3=\{e,(1\,2\,3),(1\,3\,2)\}\cong\mathbb{Z}/3\mathbb{Z}$. $A_4$ has no element of order $6$: a $6$-cycle is odd, and a product of disjoint $2$- and $3$-cycles is odd. Orders in $A_4$ divide $12$ but $6$ does not occur.",
      r"$|A_5|$ equals", r"$60$. $A_5$ is simple.",
      r"Including transpositions in $A_n$, or thinking $A_n$ abelian for $n\ge 4$.",
      r"Is $(1\,2)(3\,4)$ in $A_n$?", r"Yes: product of two transpositions, even.",
      r"Index $[S_n:A_n]$.", r"$2$.")
    a(556, r"Composition of permutations is function composition. Convention used here: $(\sigma\tau)(x)=\sigma(\tau(x))$ — apply $\tau$ first, then $\sigma$ (right to left). To multiply cycles, track each number through the right factor then the left. Inverse reverses cycles. Always state the convention; the other convention (left to right) reverses all products.",
      r"Compute $(1\,2)(1\,3)$ with right-to-left composition.",
      r"Apply $(1\,3)$ first, then $(1\,2)$: $1\mapsto 3\mapsto 3$, $3\mapsto 1\mapsto 2$, $2\mapsto 2\mapsto 1$, so $(1\,3\,2)$.",
      r"$(1\,2\,3)(1\,2)$ (right first)", r"Apply $(1\,2)$ then $(1\,2\,3)$: $1\mapsto 2\mapsto 3$, $2\mapsto 1\mapsto 2$, $3\mapsto 3\mapsto 1$, so $(1\,3)$.",
      r"Mixing left-to-right and right-to-left in the same computation.",
      r"$(1\,2\,3)^2$.", r"$(1\,3\,2)$.",
      r"Inverse of $(1\,4\,2)(3\,5)$.", r"$(2\,4\,1)(3\,5)=(1\,2\,4)(3\,5)$.")

    # M cosets & Lagrange
    a(557, r"A left coset of $H\le G$ is $aH=\{ah:h\in H\}$. Left cosets partition $G$. $|aH|=|H|$ (map $h\mapsto ah$ is bijective). $aH=bH$ iff $a^{-1}b\in H$ iff $a\in bH$. Distinct left cosets are disjoint. $G$ is the disjoint union of the left cosets of $H$.",
      r"Left cosets of $H=\{e,(1\,2)\}$ in $S_3$.",
      r"$H=\{e,(1\,2)\}$, $(1\,3)H=\{(1\,3),(1\,3)(1\,2)\}=\{(1\,3),(1\,2\,3)\}$, $(2\,3)H=\{(2\,3),(2\,3)(1\,2)\}=\{(2\,3),(1\,3\,2)\}$. Three cosets of size $2$.",
      r"Left cosets of $n\mathbb{Z}$ in $\mathbb{Z}$", r"Residue classes $r+n\mathbb{Z}$ for $r=0,\ldots,n-1$.",
      r"Writing $Ha$ when the problem asked for left cosets $aH$ in a nonabelian group.",
      r"Does $2+3\mathbb{Z}=5+3\mathbb{Z}$?", r"Yes, $2-5=-3\in 3\mathbb{Z}$.",
      r"$|aH|$ versus $|H|$.", r"Always equal.")
    a(558, r"A right coset is $Ha=\{ha:h\in H\}$. Right cosets also partition $G$ with the same cardinality $|H|$. In an abelian group, $aH=Ha$. In general left and right cosets need not coincide; they do for all $a$ iff $H$ is normal. $Ha=Hb$ iff $ab^{-1}\in H$.",
      r"Right cosets of $H=\{e,(1\,2)\}$ in $S_3$, compared with the left cosets.",
      r"$H(1\,3)=\{(1\,3),(1\,2)(1\,3)\}=\{(1\,3),(1\,3\,2)\}$, which is not the left coset $(1\,3)H=\{(1\,3),(1\,2\,3)\}$. So left $\neq$ right.",
      r"In an abelian group, left cosets versus right", r"They coincide: $a+H=H+a$.",
      r"Concluding $H$ is normal because some one left coset equals some right coset (need $aH=Ha$ for all $a$).",
      r"$H3$ for $H=2\mathbb{Z}$ in $\mathbb{Z}$.", r"$3+2\mathbb{Z}$, the odds.",
      r"Is $SL_n(\mathbb{R})\cdot A = A\cdot SL_n(\mathbb{R})$ for all $A\in GL_n$?", r"Yes: $SL_n$ is normal (kernel of det).")
    a(559, r"Coset equality: $aH=bH\Leftrightarrow a^{-1}b\in H\Leftrightarrow b^{-1}a\in H$. Equivalence relation $a\sim b$ iff $a^{-1}b\in H$ (left). The equivalence classes are the left cosets. You never ‘add representatives’ without a normality guarantee. Distinct representatives can label the same coset.",
      r"In $\mathbb{Z}$, when is $a+6\mathbb{Z}=b+6\mathbb{Z}$?",
      r"Iff $6\mid(a-b)$. So $17+6\mathbb{Z}=5+6\mathbb{Z}$ because $12$ is a multiple of $6$.",
      r"$aH=H$ iff", r"$a\in H$.",
      r"Canceling $aH=bH$ to $a=b$.",
      r"In $S_3$, is $(1\,2\,3)H=(1\,3\,2)H$ for $H=A_3$?", r"Yes: both $3$-cycles lie in $A_3$, so both cosets equal $H$ itself.",
      r"If $aH=bH$ and $H$ is finite, then", r"$a$ and $b$ differ by an element of $H$; $|aH|=|bH|=|H|$.")
    a(560, r"The index $[G:H]$ is the number of distinct left cosets of $H$ in $G$ (equal to the number of right cosets). If $G$ is finite, $[G:H]=|G|/|H|$. Index can be infinite: $[\mathbb{Z}:\{0\}]=\infty$, $[\mathbb{Z}:n\mathbb{Z}]=n$. Multiplicativity: $[G:K]=[G:H][H:K]$ when $K\le H\le G$.",
      r"Compute $[S_3:A_3]$ and $[\mathbb{Z}:4\mathbb{Z}]$.",
      r"$|S_3|/|A_3|=6/3=2$. $[\mathbb{Z}:4\mathbb{Z}]=4$.",
      r"Index of $SL_n(\mathbb{R})$ in $GL_n(\mathbb{R})$", r"Infinite: det takes all of $\mathbb{R}^\times$, so $[GL:SL]=|\mathbb{R}^\times|$. More cleanly the cosets are determined by det, infinitely many.",
      r"Writing $[G:H]=|H|/|G|$.",
      r"$[A_4:V]$ for the Klein four $V\trianglelefteq A_4$.", r"$12/4=3$.",
      r"If $[G:H]=2$, then $H$ is", r"normal (left cosets $=$ right cosets: $H$ and its complement).")
    a(561, r"Lagrange's theorem: if $H\le G$ and $G$ is finite, then $|H|$ divides $|G|$. Proof: the left cosets partition $G$ into $[G:H]$ sets each of size $|H|$. Consequence: $|g|$ divides $|G|$ for every $g$. The converse is false: $A_4$ has order $12$ but no subgroup of order $6$.",
      r"Possible orders of subgroups of a group of order $15$. Does $A_4$ have a subgroup of order $6$?",
      r"Divisors of $15$: $1,3,5,15$. (In fact groups of order $15$ are cyclic, so all occur.) $A_4$: no subgroup of order $6$, even though $6\mid 12$.",
      r"Order of any element of $S_7$ divides", r"$5040=7!$, but more usefully the lcm of cycle lengths $\le 7$.",
      r"Concluding a subgroup of every dividing order exists (converse of Lagrange / Sylow without hypotheses).",
      r"Can $\mathbb{Z}/8\mathbb{Z}$ have a subgroup of order $3$?", r"No: $3\nmid 8$.",
      r"If $|G|=p$ prime, subgroups of $G$ are", r"only $\{e\}$ and $G$.")
    a(562, r"Lagrange consequences: $g^{|G|}=e$ (finite $G$); Fermat/Euler in unit groups; groups of prime order are cyclic; at most one subgroup of a given prime order if it is unique of that order it is normal. Cauchy: if $p\mid|G|$ then some element has order $p$ (not a corollary of Lagrange alone). Index $2$ $\Rightarrow$ normal. $A_4$ shows $6\mid 12$ need not give a subgroup.",
      r"Why is every group of order $17$ cyclic? Why is there no element of order $6$ in $A_4$?",
      r"Order $17$ prime: any $g\neq e$ has order $17$, so $\langle g\rangle=G$. $A_4$ has no element of order $6$, hence cannot have a cyclic subgroup of order $6$; in fact it has no subgroup of order $6$ at all.",
      r"$a^6=e$ for all $a$ in a group of order $6$?", r"Yes, Lagrange. (In $S_3$ element orders are $1,2,3$, all dividing $6$.)",
      r"Using $g^{|G|}=e$ in an infinite group, or claiming Cauchy from Lagrange without proof.",
      r"Does $g^{12}=e$ for all $g\in A_4$?", r"Yes by Lagrange; orders actually $1,2,3$.",
      r"Unique subgroup of index $2$ is always", r"normal (the left/right cosets are $H$ and $G\setminus H$).")
    a(563, r"Subgroups of a cyclic group: if $G=\langle g\rangle$ has order $n$, then for each $d\mid n$ there is a unique subgroup of order $d$, namely $\langle g^{n/d}\rangle$. It is cyclic. Infinite cyclic $\mathbb{Z}$ has unique subgroup of each finite index $n$, namely $n\mathbb{Z}$, and they are all cyclic. Subgroups of $\mathbb{Z}/n\mathbb{Z}$ correspond to divisors of $n$.",
      r"Subgroups of $\mathbb{Z}/12\mathbb{Z}$. Which has order $4$?",
      r"Divisors $1,2,3,4,6,12$. Unique of order $4$: $\langle 3\rangle=\{0,3,6,9\}$. Unique of order $6$: $\langle 2\rangle=\{0,2,4,6,8,10\}$.",
      r"Number of subgroups of a cyclic group of order $p^3$", r"$4$: orders $1,p,p^2,p^3$.",
      r"Claiming uniqueness of a subgroup of order $d$ in a noncyclic group (Klein has three order-$2$ subgroups).",
      r"The unique subgroup of order $5$ in $\mathbb{Z}/10\mathbb{Z}$.", r"$\langle 2\rangle=\{0,2,4,6,8\}$.",
      r"Subgroups of $(\mathbb{Z},+)$.", r"$n\mathbb{Z}$ for $n\ge 0$.")

    # M homomorphisms & quotients
    a(564, r"A group homomorphism is a map $\phi:G\to K$ with $\phi(ab)=\phi(a)\phi(b)$. Then $\phi(e_G)=e_K$ and $\phi(a^{-1})=\phi(a)^{-1}$. Examples: $\det:GL_n\to F^\times$, $\mathrm{sgn}:S_n\to\{\pm 1\}$, $\exp:(\mathbb{R},+)\to(\mathbb{R}_{>0},\cdot)$, reduction $\mathbb{Z}\to\mathbb{Z}/n\mathbb{Z}$, inclusion of a subgroup. Homomorphisms preserve orders of elements in the sense $\mathrm{ord}(\phi(g))\mid\mathrm{ord}(g)$.",
      r"Show $\phi:\mathbb{Z}\to\mathbb{Z}$ given by $\phi(n)=2n$ is a homomorphism. Is $\det:GL_2(\mathbb{R})\to\mathbb{R}^\times$ a homomorphism?",
      r"$\phi(n+m)=2(n+m)=2n+2m$. Yes $\det(AB)=\det A\det B$ with kernel $SL_2$. (On all of $M_2$ the same identity holds, but $M_2$ is not a multiplicative group.)",
      r"$\phi:G\to K$ a hom. $\phi(g^k)$ equals", r"$\phi(g)^k$.",
      r"Requiring $\phi(ab)=\phi(b)\phi(a)$ (that is an anti-homomorphism) or forgetting to check the identity.",
      r"Is $x\mapsto |x|$ a hom $(\mathbb{R}^\times,\cdot)\to(\mathbb{R}_{>0},\cdot)$?", r"Yes: $|xy|=|x||y|$.",
      r"The zero map $\mathbb{Z}\to\mathbb{Z}$, $n\mapsto 0$: a hom of additive groups?", r"Yes.")
    a(565, r"The kernel of $\phi:G\to K$ is $\ker\phi=\{g\in G:\phi(g)=e_K\}$. It is always a normal subgroup of $G$. $\phi$ is injective iff $\ker\phi=\{e\}$. Computation: $\phi(a)=\phi(b)$ iff $a^{-1}b\in\ker\phi$. Examples: $\ker\det=SL_n$, $\ker\mathrm{sgn}=A_n$, $\ker(\mathbb{Z}\to\mathbb{Z}/n\mathbb{Z})=n\mathbb{Z}$.",
      r"Kernel of $\phi:\mathbb{Z}\to\mathbb{Z}/6\mathbb{Z}$, $\phi(n)=2n\bmod 6$.",
      r"$2n\equiv 0\pmod{6}$ iff $3\mid n$, so $\ker=3\mathbb{Z}$. Note: not injective, image is $\{0,2,4\}\le\mathbb{Z}/6\mathbb{Z}$.",
      r"$\ker(\mathrm{sgn}:S_n\to\{\pm 1\})$", r"$A_n$.",
      r"Thinking the kernel is a subset of the codomain, or that $\ker\phi=H$ implies $\phi$ is the quotient map without checking surjectivity.",
      r"Kernel of $\exp:(\mathbb{R},+)\to\mathbb{C}^\times$.", r"$\{0\}$, since $e^x=1$ for real $x$ iff $x=0$.",
      r"If $\ker\phi=G$, then $\phi$ is", r"the trivial homomorphism.")
    a(566, r"The image $\mathrm{im}\,\phi=\phi(G)$ is a subgroup of the codomain. $\phi$ is surjective iff $\mathrm{im}\,\phi$ equals the codomain. $|\mathrm{im}\,\phi|=[G:\ker\phi]$ when this index is finite. First isomorphism theorem identifies $\mathrm{im}\,\phi$ with $G/\ker\phi$.",
      r"Image of $\phi:\mathbb{Z}\to\mathbb{Z}/12\mathbb{Z}$, $\phi(n)=8n$.",
      r"$8n\bmod 12$: $8\cdot 0=0$, $8\cdot 1=8$, $8\cdot 2=16\equiv 4$, $8\cdot 3=24\equiv 0$, so $\mathrm{im}=\{0,4,8\}\cong\mathbb{Z}/3\mathbb{Z}$.",
      r"Image of $\det:GL_n(\mathbb{R})\to\mathbb{R}^\times$", r"all of $\mathbb{R}^\times$ (diagonal matrices with one nonzero entry $\lambda$).",
      r"Calling the image a subset of the domain.",
      r"Image of $\mathrm{sgn}:S_n\to\mathbb{Z}^\times=\{\pm 1\}$.", r"All of $\{\pm 1\}$ for $n\ge 2$.",
      r"If $\phi:G\to G$ is $\phi(g)=e$, image is", r"$\{e\}$.")
    a(567, r"A homomorphism is injective iff $\ker=\{e\}$, iff it is a monomorphism, iff it embeds $G$ as a subgroup of the codomain. It is surjective iff $\mathrm{im}$ is the whole codomain (epimorphism). A bijective hom is an isomorphism; the inverse map is automatically a hom. Finite groups: injective $\Leftrightarrow$ surjective when $|G|=|K|$.",
      r"Is $\phi:\mathbb{Z}/4\mathbb{Z}\to\mathbb{Z}/6\mathbb{Z}$, $\phi([x]_4)=[3x]_6$ well-defined and injective?",
      r"Well-defined: $x\equiv x'\pmod{4}$ $\Rightarrow$ $3x\equiv 3x'\pmod{12}$ hence $\pmod{6}$? $x=x'+4k$, $3x=3x'+12k\equiv 3x'\pmod{6}$. Kernel: $3x\equiv 0\pmod{6}$ iff $x$ even, so $\ker=\{0,2\}\neq 0$, not injective.",
      r"Inclusion $n\mathbb{Z}\hookrightarrow\mathbb{Z}$ is", r"injective, not surjective for $n\neq\pm 1$.",
      r"Checking $\phi(a)=\phi(b)\Rightarrow a=b$ only on generators and skipping the kernel test.",
      r"Can an injective hom $\mathbb{Z}/2\to S_3$ exist?", r"Yes: send the generator to any transposition.",
      r"If $|G|=|K|$ finite and $\phi:G\to K$ is a hom with trivial kernel, then", r"it is an isomorphism.")
    a(568, r"An isomorphism is a bijective homomorphism. Write $G\cong K$. Isomorphism preserves order, being abelian/cyclic, numbers of elements of each order, subgroup lattices up to iso, and solvability of equations $x^n=e$. $\mathbb{Z}/2\times\mathbb{Z}/2\not\cong\mathbb{Z}/4$ (max order $2$ vs $4$). $(\mathbb{R},+)\cong(\mathbb{R}_{>0},\cdot)$ via $\exp$. Cayley: $G\cong$ a subgroup of $S_G$.",
      r"Are $\mathbb{Z}/4\mathbb{Z}$ and $\mathbb{Z}/2\mathbb{Z}\times\mathbb{Z}/2\mathbb{Z}$ isomorphic? Are $U(5)$ and $\mathbb{Z}/4\mathbb{Z}$?",
      r"No: $\mathbb{Z}/4$ has an element of order $4$; Klein does not. $U(5)=\{1,2,3,4\}$ is cyclic of order $4$ generated by $2$, so yes $\cong\mathbb{Z}/4$.",
      r"$S_3\cong D_3$ (symmetries of the triangle)?", r"Yes.",
      r"Matching only the orders of the groups and declaring them isomorphic.",
      r"Is $(\mathbb{Q},+)\cong(\mathbb{Q}_{>0},\cdot)$?", r"No. Additive $\mathbb{Q}$ is divisible: $2x=a$ always has a solution. In $(\mathbb{Q}_{>0},\cdot)$ the equation $x^2=2$ has none. (Equivalently $\mathbb{Q}_{>0}^\times$ is free abelian on the primes.)",
      r"$\mathbb{Z}\cong n\mathbb{Z}$ via $k\mapsto nk$.", r"Yes, for $n\neq 0$.")
    a(569, r"An automorphism is an isomorphism $G\to G$. $\mathrm{Aut}(G)$ is a group under composition. Inner automorphisms $x\mapsto gxg^{-1}$ form $\mathrm{Inn}(G)\cong G/Z(G)$. $\mathrm{Aut}(\mathbb{Z})\cong\mathbb{Z}/2\mathbb{Z}$ (send $1\mapsto\pm 1$). $\mathrm{Aut}(\mathbb{Z}/n\mathbb{Z})\cong(\mathbb{Z}/n\mathbb{Z})^\times$. $\mathrm{Aut}(\mathbb{Z}/2\times\mathbb{Z}/2)\cong S_3$.",
      r"Describe $\mathrm{Aut}(\mathbb{Z}/5\mathbb{Z})$ and its order.",
      r"Automorphisms send $[1]$ to a generator $[k]$ with $\gcd(k,5)=1$, so $k=1,2,3,4$. $\mathrm{Aut}\cong U(5)\cong\mathbb{Z}/4\mathbb{Z}$, order $4$.",
      r"$|\mathrm{Aut}(\mathbb{Z}/8\mathbb{Z})|$ equals", r"$\phi(8)=4$. Explicitly $k\mapsto$ odd $k$.",
      r"Thinking every automorphism is inner (false for abelian $G$ with $\mathrm{Aut}$ nontrivial: $\mathrm{Inn}$ is trivial).",
      r"$\mathrm{Aut}(\mathbb{Z})$.", r"$\{id, n\mapsto -n\}\cong C_2$.",
      r"Inner automorphisms of an abelian group.", r"Only the identity.")
    a(570, r"A subgroup $N\le G$ is normal ($N\trianglelefteq G$) iff $gNg^{-1}=N$ for all $g$, iff $gN=Ng$ for all $g$, iff $N$ is a union of conjugacy classes, iff $N=\ker\phi$ for some hom $\phi$. Index $2$ $\Rightarrow$ normal. $A_n\trianglelefteq S_n$, $SL_n\trianglelefteq GL_n$, $n\mathbb{Z}\trianglelefteq\mathbb{Z}$. In abelian groups every subgroup is normal.",
      r"Is $\langle(1\,2)\rangle$ normal in $S_3$? Is $A_3$?",
      r"No: conjugate $(1\,3)(1\,2)(1\,3)=(2\,3)\notin\langle(1\,2)\rangle$. $A_3$ has index $2$, hence normal.",
      r"Kernel of a homomorphism is always", r"normal.",
      r"Checking $gHg^{-1}\subseteq H$ for generators $g$ of $G$ but forgetting $g^{-1}$ (need all $g$, or check a generating set carefully).",
      r"Are all subgroups of $Q_8$ normal?", r"Yes (it is Hamiltonian / all subgroups normal).",
      r"Index-$2$ subgroup of $D_4$: the rotation subgroup. Normal?", r"Yes.")
    a(571, r"If $N\trianglelefteq G$, the quotient group $G/N$ is the set of (left=right) cosets with $(aN)(bN)=abN$. Identity $N$, inverse $(aN)^{-1}=a^{-1}N$. Well-definedness uses normality. $|G/N|=[G:N]$. Examples: $\mathbb{Z}/n\mathbb{Z}$, $S_n/A_n\cong\mathbb{Z}/2$, $GL_n/SL_n\cong F^\times$.",
      r"Describe $\mathbb{Z}/4\mathbb{Z}$ as a quotient of $\mathbb{Z}$, and $S_3/A_3$.",
      r"$\mathbb{Z}/4\mathbb{Z}$ is $\mathbb{Z}/4\mathbb{Z}$ (cosets of $4\mathbb{Z}$). $S_3/A_3=\{A_3, (1\,2)A_3\}\cong C_2$.",
      r"Order of $G/N$ when $|G|=24$, $|N|=6$", r"$4$.",
      r"Multiplying cosets as $aN\cdot bN=abN$ when $N$ is not normal (not well-defined).",
      r"Is $\mathbb{Z}/2\mathbb{Z}$ a quotient of $\mathbb{Z}/4\mathbb{Z}$?", r"Yes: $\langle 2\rangle$ is normal, quotient order $2$.",
      r"Identity element of $G/N$.", r"The coset $N$.")
    a(572, r"First isomorphism theorem: if $\phi:G\to K$ is a homomorphism, then $G/\ker\phi\cong\mathrm{im}\,\phi$, via $g\ker\phi\mapsto\phi(g)$. Strategy: to identify a quotient, exhibit a surjective hom with that kernel. Examples: $\mathbb{Z}/n\mathbb{Z}\cong$ image of $\mathbb{Z}\to\mathbb{Z}/n\mathbb{Z}$; $GL_n/SL_n\cong F^\times$; $S_n/A_n\cong\{\pm 1\}$.",
      r"Identify $\mathbb{R}^\times/\{\pm 1\}$ using the first iso theorem.",
      r"Absolute value $|\,\cdot\,|:\mathbb{R}^\times\to\mathbb{R}_{>0}$ is a surjective hom with kernel $\{\pm 1\}$. So $\mathbb{R}^\times/\{\pm 1\}\cong\mathbb{R}_{>0}$.",
      r"$S_n/A_n\cong$", r"$\mathbb{Z}/2\mathbb{Z}$ via sign.",
      r"Writing $G/\mathrm{im}\,\phi\cong\ker\phi$ (swapping kernel and image).",
      r"Quotient $\mathbb{Z}/6\mathbb{Z}\big/\langle 2\rangle$.", r"$\langle 2\rangle=\{0,2,4\}\cong\mathbb{Z}/3$, quotient order $2\cong\mathbb{Z}/2$.",
      r"det induces $GL_2(\mathbb{R})/SL_2(\mathbb{R})\cong$", r"$\mathbb{R}^\times$.")
    a(573, r"Second isomorphism theorem: if $H\le G$ and $N\trianglelefteq G$, then $HN\le G$, $H\cap N\trianglelefteq H$, and $HN/N\cong H/(H\cap N)$. Third: if $N\le K\le G$ with $N,K\trianglelefteq G$, then $K/N\trianglelefteq G/N$ and $(G/N)/(K/N)\cong G/K$. Correspondence theorem: subgroups of $G/N$ biject with subgroups of $G$ containing $N$.",
      r"Apply the second iso theorem to $H=4\mathbb{Z}$, $N=6\mathbb{Z}$ in $\mathbb{Z}$.",
      r"$HN=2\mathbb{Z}$ (gcd $2$), $H\cap N=12\mathbb{Z}$. Then $2\mathbb{Z}/6\mathbb{Z}\cong 4\mathbb{Z}/12\mathbb{Z}$, both cyclic of order $3$.",
      r"Third iso: $(\mathbb{Z}/12\mathbb{Z})/(4\mathbb{Z}/12\mathbb{Z})\cong$", r"$\mathbb{Z}/4\mathbb{Z}$. Here $4\mathbb{Z}/12\mathbb{Z}=\langle 4\rangle=\{0,4,8\}$ in $\mathbb{Z}/12\mathbb{Z}$, order $3$, and $(\mathbb{Z}/12)/(\mathbb{Z}/3)\cong\mathbb{Z}/4$.",
      r"Applying second iso when $N$ is not normal in $G$ (need $N$ normal, or at least $H$ in the normalizer).",
      r"Subgroups of $\mathbb{Z}/6\mathbb{Z}$ correspond to subgroups of $\mathbb{Z}$ containing $6\mathbb{Z}$.", r"$6\mathbb{Z}\le d\mathbb{Z}\le\mathbb{Z}$ iff $d\mid 6$: $d=1,2,3,6$.",
      r"$HN/N$ has order $|H|/|H\cap N|$ when finite.", r"Yes, by the second iso theorem.")

    # M group actions
    a(574, r"A (left) group action of $G$ on a set $X$ is a map $G\times X\to X$, $(g,x)\mapsto g\cdot x$, with $e\cdot x=x$ and $(gh)\cdot x=g\cdot(h\cdot x)$. Equivalent: a homomorphism $G\to S_X$. Examples: $S_n$ on $\{1,\ldots,n\}$; $G$ on itself by left multiplication (Cayley) or by conjugation; $GL(V)$ on $V$; $G$ on left cosets $G/H$.",
      r"The map $GL_2(\mathbb{R})\times\mathbb{R}^2\to\mathbb{R}^2$, $(A,v)\mapsto Av$ is an action. What is the associated hom $GL_2\to S_{\mathbb{R}^2}$?",
      r"Each invertible matrix is sent to the permutation of $\mathbb{R}^2$ given by left-multiplication by $A$. Kernel of $G\to S_X$ is the kernel of the action (elements acting as the identity map).",
      r"Left multiplication action of $G$ on $G$ is free: stabilizer of each point is", r"$\{e\}$.",
      r"Using a right formula $(gh)\cdot x=h\cdot(g\cdot x)$ while claiming a left action.",
      r"Does $n\cdot x=x+n$ define an action of $(\mathbb{Z},+)$ on $\mathbb{R}$?", r"Yes.",
      r"Trivial action: $g\cdot x=x$ for all $g$. Associated hom?", r"The trivial hom $G\to S_X$.")
    a(575, r"The orbit of $x\in X$ is $G\cdot x=\{g\cdot x:g\in G\}$. Orbits partition $X$. The action is transitive if there is one orbit. Examples: $S_n$ is transitive on $\{1,\ldots,n\}$. $SO(2)$ on $\mathbb{R}^2$ has orbits $\{0\}$ and the circles of each radius $r>0$ (rotations preserve length).",
      r"Orbits of $\{\pm 1\}$ acting on $\mathbb{R}$ by multiplication.",
      r"Orbit of $0$ is $\{0\}$. Orbit of $x\neq 0$ is $\{x,-x\}$.",
      r"Number of orbits of $S_4$ on $\{1,2,3,4\}$", r"$1$ (transitive).",
      r"Confusing orbit with stabilizer, or thinking orbits can overlap nontrivially.",
      r"Orbits of $\mathbb{Z}$ acting on $\mathbb{Z}/6\mathbb{Z}$ by addition? Addition of $\mathbb{Z}$ on itself?", r"On $\mathbb{Z}/6$ by $n\cdot[x]=[x+n]$: one orbit (transitive).",
      r"Rotation group $C_4$ of the square acting on $4$ vertices: orbit of a vertex?", r"All $4$ vertices.")
    a(576, r"The stabilizer of $x$ is $G_x=\{g\in G:g\cdot x=x\}$, a subgroup of $G$. The kernel of the action is $\bigcap_x G_x$, always normal. Points in the same orbit have conjugate (hence isomorphic) stabilizers: $G_{g\cdot x}=g G_x g^{-1}$. Fixed points are those with $G_x=G$.",
      r"Stabilizer of $1$ in the usual action of $S_3$ on $\{1,2,3\}$.",
      r"$G_1=\{e,(2\,3)\}\cong\mathbb{Z}/2\mathbb{Z}$.",
      r"Stabilizer of a vector $v\neq 0$ under $GL(V)$", r"the matrices with $Av=v$, an affine slice of $GL$; in particular not all of $GL$.",
      r"Thinking $G_x$ is a subset of $X$.",
      r"Stabilizer of $0$ for $GL_n$ on $F^n$.", r"All of $GL_n$ (every linear map fixes $0$).",
      r"If the action is free, every stabilizer is", r"$\{e\}$.")
    a(577, r"Orbit-stabilizer: $|G\cdot x|=[G:G_x]$. If $G$ is finite, $|G|=|G\cdot x|\,|G_x|$. This computes orbit sizes and $|G|$ (e.g. $|S_n|=n\cdot(n-1)!$ by stab of $1$ isomorphic to $S_{n-1}$). Counting formula: $|X|=\sum |G|/|G_{x_i}|$ summed over orbit representatives.",
      r"Verify orbit-stabilizer for $S_3$ acting on $\{1,2,3\}$ at the point $1$.",
      r"Orbit of $1$ has size $3$, $|G_1|=2$, product $6=|S_3|$.",
      r"$|GL_2(\mathbb{F}_p)|$ by choosing images of a basis: first column", r"$p^2-1$ nonzero vectors, second $p^2-p$ not a multiple of the first: $(p^2-1)(p^2-p)$. Orbit-stab on the set of bases.",
      r"Using $|G|=|G\cdot x|+|G_x|$.",
      r"Size of the orbit of a vertex under $D_4$ (order $8$).", r"Stabilizer of a vertex is $\{e,$ reflection through that vertex$\}$, order $2$, orbit $4$.",
      r"If $|G|=12$ and $|G_x|=4$, the orbit has size", r"$3$.")
    a(578, r"Conjugacy in $G$: $a$ is conjugate to $b$ if $b=gag^{-1}$ for some $g$. This is an equivalence relation. Conjugation is an automorphism: it preserves order, cycle type in $S_n$ (relabeling), and being a generator. The conjugacy class of $a$ is the orbit under the conjugation action. $a$ is central iff its class is $\{a\}$.",
      r"Conjugate $(1\,2\,3)$ by $(1\,4)$ in $S_4$.",
      r"$\sigma\tau\sigma^{-1}$ replaces each label $i$ in $\tau$ by $\sigma(i)$: $(4\,2\,3)$.",
      r"In an abelian group, conjugacy classes are", r"singletons.",
      r"Conjugating a cycle by rewriting numbers without applying $\sigma$ to every entry.",
      r"Are $(1\,2)$ and $(3\,4)$ conjugate in $S_4$?", r"Yes: same cycle type.",
      r"Are they conjugate in $A_4$?", r"No: transpositions are odd, so they do not even lie in $A_4$.")
    a(579, r"Conjugacy classes partition $G$. The class equation: $|G|=|Z(G)|+\sum |cl(a_i)|$ over representatives of non-central classes, and each class size $|cl(a)|=[G:C_G(a)]$ divides $|G|$. $p$-groups have nontrivial center. Class sizes in $S_n$ are $n!$ divided by the centralizer order computed from cycle type.",
      r"Class equation of $S_3$.",
      r"Classes: $\{e\}$, the three transpositions, the two $3$-cycles. $6=1+3+2$. Center trivial.",
      r"Class size of a $3$-cycle in $S_4$", r"Number of $3$-cycles: $\binom{4}{3}\cdot 2=8$. (The leftover letter is fixed.)",
      r"Adding class sizes that do not divide $|G|$.",
      r"Does a class of size $2$ exist in a group of order $15$?", r"$2\nmid 15$, no.",
      r"Center of a $p$-group.", r"Nontrivial (class equation: $p\mid|G|$ and $p$ divides noncentral class sizes, so $p\mid|Z|$).")
    a(580, r"The external direct product $G\times H$ has operation $(g,h)(g',h')=(gg',hh')$. Then $G\times\{e\}\cong G$ and $\{e\}\times H\cong H$ are normal subgroups intersecting trivially and generating the product. $G\times H$ is abelian iff both factors are. $\mathbb{Z}/m\times\mathbb{Z}/n\cong\mathbb{Z}/mn$ iff $\gcd(m,n)=1$. Internal direct product: $G=NK$ with $N\cap K=\{e\}$, $N,K\trianglelefteq G$, and elements of $N$ commuting with those of $K$ in the strong sense $nk=kn$ — equivalently the product map $N\times K\to G$ is an iso.",
      r"Is $\mathbb{Z}/2\times\mathbb{Z}/3\cong\mathbb{Z}/6$? Is $\mathbb{Z}/2\times\mathbb{Z}/2\cong\mathbb{Z}/4$?",
      r"Yes, $\gcd(2,3)=1$. No: Klein vs cyclic.",
      r"$|G\times H|$ equals", r"$|G|\,|H|$.",
      r"Claiming $G\times H\cong G$ whenever $H$ is nontrivial (only the trivial factor can be dropped).",
      r"Center of $G\times H$.", r"$Z(G)\times Z(H)$.",
      r"Is $S_3\times\mathbb{Z}/2$ abelian?", r"No.")
    a(581, r"Classification of finite abelian groups: every finite abelian group is isomorphic to a unique product $\mathbb{Z}/n_1\mathbb{Z}\times\cdots\times\mathbb{Z}/n_k\mathbb{Z}$ with $n_{i+1}\mid n_i$ (invariant factors), and also to a unique product of cyclic groups of prime-power order $\prod\mathbb{Z}/p_i^{e_i}\mathbb{Z}$ (elementary divisors), unique up to ordering. The two forms convert by grouping prime powers and using CRT when exponents allow.",
      r"List the abelian groups of order $12$ up to isomorphism, in both forms.",
      r"Elementary divisors: $\mathbb{Z}/4\times\mathbb{Z}/3\cong\mathbb{Z}/12$ and $\mathbb{Z}/2\times\mathbb{Z}/2\times\mathbb{Z}/3\cong\mathbb{Z}/2\times\mathbb{Z}/6$. Invariant factors: $\mathbb{Z}/12$ and $\mathbb{Z}/6\times\mathbb{Z}/2$. Two groups.",
      r"Number of abelian groups of order $p^3$", r"Three: $\mathbb{Z}/p^3$, $\mathbb{Z}/p^2\times\mathbb{Z}/p$, $\mathbb{Z}/p\times\mathbb{Z}/p\times\mathbb{Z}/p$.",
      r"Forgetting the divisibility condition and listing $\mathbb{Z}/2\times\mathbb{Z}/4$ as a third invariant-factor form of order $8$ distinct from $\mathbb{Z}/4\times\mathbb{Z}/2$ (they are the same up to order).",
      r"Abelian groups of order $pq$, distinct primes.", r"Only $\mathbb{Z}/pq$ (CRT).",
      r"Is $\mathbb{Z}/2\times\mathbb{Z}/2\times\mathbb{Z}/3\cong\mathbb{Z}/6\times\mathbb{Z}/2$?", r"Yes.")

    # N rings
    a(582, r"A ring $R$ is an abelian group $(R,+)$ with an associative multiplication distributive over addition: $a(b+c)=ab+ac$, $(b+c)a=ba+ca$. Many texts require a multiplicative identity $1\neq 0$. Additive identity $0$ satisfies $0\cdot a=a\cdot 0=0$. Examples: $\mathbb{Z}$, $\mathbb{Z}/n\mathbb{Z}$, $F[x]$, $M_n(F)$, $\mathbb{Z}[i]$. Nonexample: $(\mathbb{N},+,\cdot)$ is not an additive group.",
      r"Which axioms fail for $(\mathbb{N},+,\cdot)$? Verify $0\cdot a=0$ in any ring.",
      r"No additive inverses (except $0$). $0\cdot a=(0+0)\cdot a=0\cdot a+0\cdot a$, cancel to $0=0\cdot a$.",
      r"$M_2(\mathbb{R})$ is a ring. Commutative?", r"No.",
      r"Requiring every nonzero element to have a multiplicative inverse (that is a field, or a division ring if noncommutative).",
      r"Is $C(\mathbb{R},\mathbb{R})$ of continuous functions a ring?", r"Yes, pointwise $+,\cdot$.",
      r"Additive inverse of $a$ in a ring. Product $(-1)a$ if $1$ exists?", r"Equals $-a$.")
    a(583, r"A ring is commutative if $ab=ba$ for all $a,b$. $\mathbb{Z}$, $\mathbb{Z}/n\mathbb{Z}$, $F[x]$, $\mathbb{Z}[i]$ are commutative; $M_n(F)$ for $n\ge 2$ and the Hamilton quaternions $\mathbb{H}$ are not. Polynomial rings $R[x]$ are commutative iff $R$ is. Homomorphic images of commutative rings are commutative.",
      r"Give a commutative ring that is not an integral domain, and a noncommutative ring with identity.",
      r"$\mathbb{Z}/6\mathbb{Z}$: $2\cdot 3=0$. $M_2(\mathbb{R})$: identity $I_2$, not commutative.",
      r"Is $\mathbb{H}$ commutative?", r"No: $ij=k=-ji$.",
      r"Assuming $R[x]$ fails to be commutative when $R=\mathbb{Z}$ (it is commutative).",
      r"Subring of $M_2(\mathbb{R})$ isomorphic to $\mathbb{C}$.", r"Matrices $\begin{pmatrix}a&-b\\ b&a\end{pmatrix}$.",
      r"Product ring $R\times S$ is commutative iff", r"both $R$ and $S$ are.")
    a(584, r"A multiplicative identity $1_R$ satisfies $1_R a=a 1_R=a$. If it exists it is unique. A unital homomorphism sends $1_R$ to $1_S$. The ring $2\mathbb{Z}$ of even integers has no identity. Some authors require rings to be unital; then subrings share the same $1$. $1=0$ iff $R$ is the zero ring.",
      r"Does $2\mathbb{Z}$ have a multiplicative identity? Does $\mathbb{Z}/n\mathbb{Z}$?",
      r"$2\mathbb{Z}$: no $e$ with $e\cdot 2=2$ and $e$ even except $e=1\notin 2\mathbb{Z}$. $\mathbb{Z}/n\mathbb{Z}$ has identity $[1]$.",
      r"The identity in $M_n(F)$ is", r"$I_n$.",
      r"Taking $1$ of a subring to be a different element (e.g. $2$ in $2\mathbb{Z}$ if one pretends it is unital with identity $2$: then $2\cdot 4=8\neq 4$).",
      r"Can a ring with $1$ satisfy $1=0$?", r"Only the zero ring.",
      r"Units live in a unital ring. Is $-1$ always a unit?", r"Yes: $(-1)(-1)=1$.")
    a(585, r"A subring $S\subseteq R$ is a subset that is a ring under the same operations. Tests: $S$ nonempty (or $0\in S$), closed under subtraction and multiplication. If rings are unital, require $1_R\in S$. Then $n\mathbb{Z}$ is a subring of $\mathbb{Z}$ in the non-unital convention, but not unital-sharing unless $n=\pm 1$. $\mathbb{Z}\subset\mathbb{Q}\subset\mathbb{R}\subset\mathbb{C}$. Intersection of subrings is a subring.",
      r"Is $\mathbb{Z}[i]$ a subring of $\mathbb{C}$? Is $\{0,2,4\}$ a subring of $\mathbb{Z}/6\mathbb{Z}$?",
      r"Yes: Gaussian integers closed under $+,-,\cdot$, contain $1$. Second: $2\cdot 2=4$, $2\cdot 4=2$, $4\cdot 4=4\bmod 6$, additive subgroup $\{0,2,4\}$. Unital? Does not contain $1$. So a rng-subring, not a unital subring.",
      r"$\mathbb{Q}\cap\mathbb{R}$ as a subring of $\mathbb{C}$ is", r"$\mathbb{Q}$.",
      r"Checking multiplicative closure but not additive inverses.",
      r"Is $M_2(\mathbb{Z})$ a subring of $M_2(\mathbb{R})$?", r"Yes.",
      r"Smallest subring of $\mathbb{R}$ containing $1$.", r"$\mathbb{Z}$ (the prime ring of characteristic $0$).")
    a(586, r"An integral domain is a commutative unital ring $R\neq 0$ with no zero divisors: $ab=0\Rightarrow a=0$ or $b=0$. Equivalent: cancellation $ab=ac$ and $a\neq 0\Rightarrow b=c$. $\mathbb{Z}$, $F[x]$ for a field $F$, $\mathbb{Z}[i]$ are domains. $\mathbb{Z}/n\mathbb{Z}$ is a domain iff $n$ is prime (then it is a field). A finite integral domain is a field.",
      r"Which of $\mathbb{Z}/7\mathbb{Z}$, $\mathbb{Z}/8\mathbb{Z}$, $\mathbb{Z}[x]$ are integral domains?",
      r"$\mathbb{Z}/7$ is a field, hence a domain. $\mathbb{Z}/8$: $2\cdot 4=0$, not a domain. $\mathbb{Z}[x]$ is a domain because $\mathbb{Z}$ is.",
      r"Finite domains are", r"fields.",
      r"Calling $\mathbb{Z}/4\mathbb{Z}$ a domain because $4$ is a prime power.",
      r"Is $\mathbb{Z}/pq\mathbb{Z}$ a domain for distinct primes $p,q$?", r"No: $\bar p\bar q=0$.",
      r"Cancellation in $\mathbb{Z}$: $2x=2y\Rightarrow x=y$. In $\mathbb{Z}/6$?", r"No: $2\cdot 2=2\cdot 5\bmod 6$ but $2\neq 5$.")
    a(587, r"A unit of a unital ring $R$ is an element $u$ with some $v$ satisfying $uv=vu=1$. The units form a group $R^\times$. $\mathbb{Z}^\times=\{\pm 1\}$, $(\mathbb{Z}/n\mathbb{Z})^\times$ has order $\phi(n)$, $F[x]^\times=F^\times$ for a field $F$, $M_n(F)^\times=GL_n(F)$. In a field, $R^\times=R\setminus\{0\}$.",
      r"Units of $\mathbb{Z}[i]$, and of $\mathbb{Z}/8\mathbb{Z}$.",
      r"Gaussian units: $\pm 1,\pm i$ (norm $1$). $\mathbb{Z}/8$: $\{1,3,5,7\}$, each of order dividing $2$.",
      r"$(\mathbb{R}[x])^\times$ equals", r"the nonzero constant polynomials, $\mathbb{R}^\times$.",
      r"Calling every nonzero element a unit in $\mathbb{Z}$ or in $\mathbb{Z}/n$ for composite $n$.",
      r"Units of $\mathbb{Z}/9\mathbb{Z}$.", r"$1,2,4,5,7,8$ ($\phi(9)=6$).",
      r"Is $1+x$ a unit in $\mathbb{R}[[x]]$ (power series)?", r"Yes: geometric series $1-x+x^2-\cdots$.")
    a(588, r"A zero divisor is a nonzero $a$ such that $ab=0$ for some $b\neq 0$ (left/right versions in noncommutative rings). A domain has none. In $\mathbb{Z}/n\mathbb{Z}$ the zero divisors are the nonzero nonunits, i.e. residues sharing a factor with $n$. In $M_2(F)$, nilpotent nonzero matrices are zero divisors. The set of zero divisors is not typically an ideal.",
      r"Zero divisors in $\mathbb{Z}/12\mathbb{Z}$. Give a matrix zero divisor.",
      r"Nonzero and not coprime to $12$: $2,3,4,6,8,9,10$. Matrix: $\begin{pmatrix}0&1\\0&0\end{pmatrix}\begin{pmatrix}0&0\\1&0\end{pmatrix}=\begin{pmatrix}1&0\\0&0\end{pmatrix}\neq 0$, and $\begin{pmatrix}0&1\\0&0\end{pmatrix}^2=0$ so it is a (nilpotent) zero divisor.",
      r"$2$ is a zero divisor in $\mathbb{Z}/6$ because", r"$2\cdot 3=0$ and $3\neq 0$.",
      r"Calling $0$ a zero divisor (conventions usually exclude it).",
      r"Does $\mathbb{Z}$ have zero divisors?", r"No.",
      r"In $\mathbb{Z}/15$, is $5$ a unit or a zero divisor?", r"Zero divisor: $5\cdot 3=15\equiv 0$.")
    a(589, r"A ring homomorphism $\phi:R\to S$ satisfies $\phi(a+b)=\phi(a)+\phi(b)$ and $\phi(ab)=\phi(a)\phi(b)$. Unital homs also have $\phi(1_R)=1_S$. Then $\phi(0)=0$ and $\phi(-a)=-\phi(a)$. Examples: reduction $\mathbb{Z}\to\mathbb{Z}/n\mathbb{Z}$; evaluation $F[x]\to F$, $f\mapsto f(a)$; inclusion of a subring; $R\to R\times S$, $r\mapsto(r,0)$ is a non-unital hom.",
      r"The evaluation $\mathrm{ev}_2:\mathbb{Z}[x]\to\mathbb{Z}$, $f\mapsto f(2)$. Kernel?",
      r"A unital ring hom. Remainder theorem: $f=(x-2)q+f(2)$ with $q\in\mathbb{Z}[x]$ because $x-2$ is monic, so $\ker=(x-2)$.",
      r"Unique unital hom $\mathbb{Z}\to R$ for a unital ring $R$", r"$n\mapsto n\cdot 1_R$.",
      r"Forgetting multiplicativity (only checking additivity: that is a hom of abelian groups).",
      r"Reduction $\mathbb{Z}\to\mathbb{Z}/n\mathbb{Z}$ is surjective. Kernel?", r"$n\mathbb{Z}$.",
      r"Is $x\mapsto 2x$ a ring hom $\mathbb{Z}\to\mathbb{Z}$?", r"No: $2(ab)\neq (2a)(2b)$ in general.")
    a(590, r"For a ring hom $\phi:R\to S$, $\ker\phi=\{r:\phi(r)=0\}$ is an ideal of $R$, and $\mathrm{im}\,\phi$ is a subring of $S$. $\phi$ is injective iff $\ker=0$. First iso theorem: $R/\ker\phi\cong\mathrm{im}\,\phi$. Unital homs have $\mathrm{im}$ unital with the same $1$ as $S$ only if $\phi(1)=1$; image then contains $1_S$.",
      r"Kernel and image of $\phi:\mathbb{Z}\to\mathbb{Z}/12\mathbb{Z}$, $\phi(n)=4n\bmod 12$.",
      r"Not unital. $\ker=\{n:12\mid 4n\}=\{n:3\mid n\}=3\mathbb{Z}$. Image $\{0,4,8\}$, a subring (without $1$ of $\mathbb{Z}/12$).",
      r"Kernel of evaluation $\mathbb{R}[x]\to\mathbb{R}$, $f\mapsto f(0)$", r"the ideal $(x)$ of polynomials with zero constant term.",
      r"Claiming the kernel is always a subring sharing $1$ (it contains $1$ iff $\phi$ is zero).",
      r"If $\ker\phi=R$, then", r"$\phi=0$ and $\mathrm{im}=\{0\}$.",
      r"Image of $\mathbb{Z}\to\mathbb{Q}$ the inclusion.", r"$\mathbb{Z}$, a subring of $\mathbb{Q}$.")

    # N ideals & quotients
    a(591, r"An (two-sided) ideal $I\subseteq R$ is an additive subgroup with $r\in R$, $a\in I\Rightarrow ra,ar\in I$ (absorbs multiplication from $R$). For commutative unital $R$ it is enough: $0\in I$, closed under addition, and $R I\subseteq I$. Examples: $n\mathbb{Z}$ in $\mathbb{Z}$; $(f)$ in $F[x]$; $\{0\}$ and $R$. Ideals of $\mathbb{Z}$ are exactly $n\mathbb{Z}$. The kernel of a ring hom is an ideal.",
      r"Show $I=\{f\in\mathbb{R}[x]:f(2)=f'(2)=0\}$ is an ideal. Is $2\mathbb{Z}$ an ideal of $\mathbb{Z}$?",
      r"$I=(x-2)^2$, an ideal. Yes, $2\mathbb{Z}=(2)$.",
      r"Are all additive subgroups of $\mathbb{Z}$ ideals?", r"Yes, they are all $n\mathbb{Z}$.",
      r"Checking $I\cdot I\subseteq I$ only (that is a subring test ingredient, not absorption by $R$).",
      r"Is $M_2(2\mathbb{Z})$ an ideal of $M_2(\mathbb{Z})$?", r"Yes: multiplying a matrix of even entries by any integer matrix keeps even entries.",
      r"The units of $R$ lie in an ideal $I$ only if", r"$I=R$ (because $1\in I$ then).")
    a(592, r"A principal ideal is generated by one element: $(a)=\{ra:r\in R\}$ in a commutative unital ring (or $RaR$ two-sided in general). $\mathbb{Z}$ and $F[x]$ are PIDs: every ideal is principal. $(2,x)$ in $\mathbb{Z}[x]$ is not principal. $(a)\subseteq(b)$ iff $b\mid a$ in a domain. $(a)=(b)$ iff $a$ and $b$ are associates.",
      r"Prove $(2,x)$ is not principal in $\mathbb{Z}[x]$.",
      r"If $(2,x)=(f)$, then $f\mid 2$ so $f=\pm 1$ or $\pm 2$ (units of $\mathbb{Z}$). $f=\pm 1$ gives $(1)=\mathbb{Z}[x]\neq(2,x)$. $f=\pm 2$: then $x\in(2)$, so $x=2g$, impossible by degrees/content.",
      r"Ideals of $\mathbb{Z}$: all principal, generated by", r"the nonnegative generator $n$.",
      r"Writing $(2,x)=(2)$ in $\mathbb{Z}[x]$ because $x$ ‘doesn’t matter’.",
      r"$(6)\cap(9)$ in $\mathbb{Z}$.", r"$(18)=\mathrm{lcm}(6,9)\mathbb{Z}$.",
      r"$(6)+(9)$ in $\mathbb{Z}$.", r"$(3)=\gcd(6,9)\mathbb{Z}$.")
    a(593, r"A proper ideal $P$ is prime if $ab\in P\Rightarrow a\in P$ or $b\in P$ (commutative unital setting). Equivalent: $R/P$ is an integral domain. In $\mathbb{Z}$, prime ideals are $(0)$ and $(p)$ for $p$ prime. In $F[x]$, $(0)$ and $(f)$ for irreducible $f$. $(0)$ is prime iff $R$ is a domain.",
      r"Which of $(4)$, $(5)$, $(0)$ are prime in $\mathbb{Z}$? Is $(x^2)$ prime in $\mathbb{Q}[x]$?",
      r"$(5)$ yes, $\mathbb{Z}/5$ a field. $(4)$ no: $2\cdot 2\in(4)$ but $2\notin(4)$. $(0)$ yes, $\mathbb{Z}$ a domain. $(x^2)$ no: $\mathbb{Q}[x]/(x^2)$ has nilpotents, not a domain.",
      r"$R/P$ is a domain iff", r"$P$ is prime.",
      r"Confusing prime ideals with prime elements when $R$ is not a domain, or thinking $(p^k)$ is prime.",
      r"Is $(x)$ prime in $\mathbb{Z}[x]$?", r"Yes: $\mathbb{Z}[x]/(x)\cong\mathbb{Z}$, a domain.",
      r"Is $(x,2)$ prime in $\mathbb{Z}[x]$?", r"Yes: quotient $\cong\mathbb{Z}/2\mathbb{Z}$, a field, so actually maximal.")
    a(594, r"A proper ideal $M$ is maximal if no ideal lies strictly between $M$ and $R$. Equivalent (commutative unital): $R/M$ is a field. Maximal $\Rightarrow$ prime. In $\mathbb{Z}$, maximal ideals are $(p)$ for $p$ prime (so $(0)$ is prime but not maximal). In $F[x]$, $(f)$ is maximal iff $f$ is irreducible.",
      r"Is $(x)$ maximal in $\mathbb{R}[x]$? In $\mathbb{Z}[x]$?",
      r"$\mathbb{R}[x]/(x)\cong\mathbb{R}$, a field: yes. $\mathbb{Z}[x]/(x)\cong\mathbb{Z}$, not a field: $(x)$ is prime not maximal. Strictly larger: $(x,2)$.",
      r"$R/M$ is a field iff", r"$M$ is maximal.",
      r"Thinking $(0)$ is maximal in $\mathbb{Z}$, or that prime $\Rightarrow$ maximal always (true in PIDs that are not fields? In a PID, nonzero prime ideals are maximal).",
      r"Maximal ideals of $\mathbb{Z}$.", r"$(p)$ for $p$ prime.",
      r"Is $(x^2+1)$ maximal in $\mathbb{R}[x]$?", r"Yes: quotient $\cong\mathbb{C}$, a field. Irreducible over $\mathbb{R}$.")
    a(595, r"If $I$ is a two-sided ideal, the quotient ring $R/I$ has cosets $a+I$ with $(a+I)+(b+I)=(a+b)+I$ and $(a+I)(b+I)=ab+I$. Zero is $I$, identity $1+I$ if $R$ is unital. $\mathbb{Z}/n\mathbb{Z}$ is the model. $F[x]/(p(x))$ is a field iff $p$ is irreducible. Correspondence: ideals of $R/I$ biject with ideals of $R$ containing $I$.",
      r"Identify $\mathbb{R}[x]/(x^2+1)$ and $\mathbb{Z}[x]/(x)$.",
      r"$\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}$ via $x\mapsto i$. $\mathbb{Z}[x]/(x)\cong\mathbb{Z}$.",
      r"$\mathbb{Z}/n\mathbb{Z}$ is a field iff", r"$n$ is prime.",
      r"Multiplying representatives without reducing, or treating $R/I$ as a subset of $R$.",
      r"Zero-divisors in $\mathbb{Z}/12\mathbb{Z}$ as a quotient.", r"Images of integers sharing a factor with $12$.",
      r"$F[x]/(x-a)\cong$", r"$F$, evaluation at $a$.")
    a(596, r"First isomorphism theorem for rings: if $\phi:R\to S$ is a ring hom, then $R/\ker\phi\cong\mathrm{im}\,\phi$ as rings. To prove $R/I\cong S$, produce a surjective hom $R\to S$ with kernel $I$. Examples: $\mathbb{Z}/n\mathbb{Z}$; $F[x]/(x-a)\cong F$; $\mathbb{Z}[x]/(x^2+1)\cong\mathbb{Z}[i]$; $\mathbb{R}[x]/(x^2+1)\cong\mathbb{C}$.",
      r"Prove $\mathbb{Z}[x]/(x^2+1)\cong\mathbb{Z}[i]$.",
      r"Evaluation at $i$: $\phi(f)=f(i)$ is a surjective ring hom $\mathbb{Z}[x]\to\mathbb{Z}[i]$. Kernel is polynomials with $f(i)=0$, i.e. $(x^2+1)$ because $x^2+1$ is the min poly of $i$ over $\mathbb{Q}$ and is monic, so it generates the kernel over $\mathbb{Z}$ as well.",
      r"$\mathbb{R}[x]/(x)\cong$", r"$\mathbb{R}$.",
      r"Producing an additive-group iso and calling it a ring iso without checking multiplication.",
      r"$F[x]/(x^2)\cong$ polynomials $a+bx$ with $x^2=0$. Is it a domain?", r"No: $\bar x\neq 0$ but $\bar x^2=0$.",
      r"Kernel of $\mathbb{Z}\to\mathbb{Z}[i]/(1+i)$, reduction. Quotient?", r"$(1+i)$ has norm $2$, quotient $\cong\mathbb{Z}/2$.")
    a(597, r"In $F[x]$, every ideal is principal $(f)$, generated by any minimal-degree nonzero element (or $0$). The ideal $(f,g)=(d)$ where $d=\gcd(f,g)$. Vanishing ideals: polynomials vanishing at $a_1,\ldots,a_k$ (distinct) equal $( (x-a_1)\cdots(x-a_k) )$ in $F[x]$. Generators can be replaced by a gcd.",
      r"Simplify $(x^2-1,x^2+x)$ in $\mathbb{Q}[x]$, and the ideal of polynomials vanishing at $0$ and $1$.",
      r"$\gcd(x^2-1,x^2+x)=\gcd(x^2-1,x(x+1))$. Euclidean: $(x^2+x)-(x^2-1)=x+1$, then $x^2-1=(x-1)(x+1)$, gcd $x+1$. So $(x+1)$. Vanishing at $0,1$: $(x(x-1))$.",
      r"$(x,x+1)$ in $F[x]$ equals", r"$(1)=F[x]$, because $\gcd=1$.",
      r"Writing $(f,g)=(fg)$ (that is the product of principal ideals only in special cases; generally $(f)\cap(g)=(lcm)$).",
      r"$(2x,4)$ in $\mathbb{Z}[x]$: principal?", r"No (similar to $(2,x)$ after scaling); contains $4$ and $2x$.",
      r"If $f\mid g$ then $(g)\subseteq(f)$.", r"Yes.")

    # N polynomial rings & factorization
    a(598, r"The polynomial ring $R[x]$ consists of polynomials $\sum_{k=0}^n a_k x^k$ with $a_k\in R$, addition coefficientwise, multiplication by Cauchy product. If $R$ is a commutative domain then so is $R[x]$, and $\deg(fg)=\deg f+\deg g$. $R[x]^\times=R^\times$ when $R$ is a reduced domain (e.g. a field or $\mathbb{Z}$). Evaluation at $a\in R$ is a hom $R[x]\to R$ if $R$ is commutative.",
      r"Degree of $(x^2+1)(x^3-x)$ in $\mathbb{Z}[x]$, and units of $\mathbb{Q}[x]$.",
      r"Degrees add: $5$. Units of $\mathbb{Q}[x]$ are the nonzero constants $\mathbb{Q}^\times$.",
      r"Is $\mathbb{Z}[x]$ a PID?", r"No: $(2,x)$ is not principal.",
      r"Treating $R[x]$ as a field when $R$ is a field (the field of fractions is $R(x)$, rational functions).",
      r"Constant term of $(1+2x)(3-x)$ in $\mathbb{Z}[x]$.", r"$3$.",
      r"If $R$ has zero divisors, can $\deg(fg)<\deg f+\deg g$?", r"Yes: $(2x)(3x)=0$ in $(\mathbb{Z}/6)[x]$.")
    a(599, r"Division algorithm in $F[x]$ for a field $F$: given $g\neq 0$, for any $f$ there exist unique $q,r$ with $f=qg+r$ and $r=0$ or $\deg r<\deg g$. Consequently $F[x]$ is Euclidean. Remainder theorem: remainder of $f$ on division by $x-a$ is $f(a)$. Factor theorem: $x-a\mid f$ iff $f(a)=0$.",
      r"Divide $x^3+x+1$ by $x+1$ in $\mathbb{Q}[x]$, and evaluate the remainder at $x=-1$.",
      r"Synthetic: coefficients $1,0,1,1$ at $-1$: $1$, $-1$, $2$, $-1$. Quotient $x^2-x+2$, remainder $-1$. Check: $f(-1)=-1-1+1=-1$.",
      r"$x-2$ divides $x^3-8$ because", r"$2^3-8=0$.",
      r"Running division over $\mathbb{Z}$ when the leading coefficient of the divisor is not a unit (cannot always divide $2x+1$ into $x$ in $\mathbb{Z}[x]$).",
      r"Remainder of $x^{10}+x$ divided by $x^2-1$ in $\mathbb{Q}[x]$.", r"Write $x^2\equiv 1$, so $x^{10}+x\equiv 1+x$. Remainder $x+1$.",
      r"Unique $q,r$ when dividing $x^2$ by $x-1$.", r"$q=x+1$, $r=1$.")
    a(600, r"A nonunit $f\in F[x]$ is irreducible over the field $F$ if $f=gh$ implies one of $g,h$ is a unit (a nonzero constant). Degree $1$ polynomials are always irreducible. Degree $2$ or $3$: irreducible iff it has no root in $F$. Higher degree may factor without having a root in $F$: $(x^2+1)^2$ is reducible over $\mathbb{R}$ yet has no real root.",
      r"Is $x^2+x+1$ irreducible over $\mathbb{F}_2$? Over $\mathbb{Q}$? Is $x^4+4$ irreducible over $\mathbb{Q}$?",
      r"Over $\mathbb{F}_2$: $f(0)=1$, $f(1)=1$, no root, degree $2$, irreducible. Over $\mathbb{Q}$: cyclotomic, irreducible. $x^4+4=(x^2+2x+2)(x^2-2x+2)$, reducible despite no rational root.",
      r"$x^2-2$ over $\mathbb{Q}$ vs $\mathbb{R}$", r"Irreducible over $\mathbb{Q}$; $(x-\sqrt{2})(x+\sqrt{2})$ over $\mathbb{R}$.",
      r"Declaring a quartic irreducible because the rational root test finds no root.",
      r"$x^2+1$ over $\mathbb{F}_5$.", r"$2^2=4\equiv -1$, so $(x-2)(x+2)$, reducible.",
      r"Any degree-$1$ polynomial over a field is", r"irreducible.")
    a(601, r"Rational root test: if $f=a_n x^n+\cdots+a_0\in\mathbb{Z}[x]$ and $p/q$ in lowest terms is a rational root, then $p\mid a_0$ and $q\mid a_n$. This produces a finite list of candidates to test. It never proves irreducibility of degree $\ge 4$ by itself; it can prove there is no rational linear factor.",
      r"Possible rational roots of $2x^3+x^2-7x-6$, and test them.",
      r"Candidates $p\mid 6$, $q\mid 2$: $\pm 1,2,3,6,\frac12,\frac32$. $f(-1)=-2+1+7-6=0$, so $x+1$ divides. Synthetic division: $2x^3+x^2-7x-6=(x+1)(2x^2-x-6)=(x+1)(2x+3)(x-2)$. Rational roots $-1,2,-3/2$.",
      r"Possible rational roots of $x^3+x+1$", r"$\pm 1$. Neither works: $1+1+1=3$, $-1-1+1=-1$. No rational root.",
      r"Testing $p/q$ with $p$ dividing the leading coefficient instead of the constant term.",
      r"Possible rational roots of $x^3-x^2-8x+12$.", r"$\pm 1,2,3,4,6,12$. $x=2$: $8-4-16+12=0$, so $2$ is a root.",
      r"Does the test list $2/3$ for $3x^2-2$?", r"Yes: $p\mid -2$, $q\mid 3$, including $2/3$. And $3(4/9)-2=-2/3\neq 0$; $f(\sqrt{2/3})$ is the real root, irrational.")
    a(602, r"A UFD has factorization into irreducibles unique up to units and order. $F[x]$ is a UFD (in fact a Euclidean domain). Gauss: $R$ UFD $\Rightarrow R[x]$ UFD, so $\mathbb{Z}[x]$ is a UFD. Content and Gauss's lemma: a primitive polynomial is irreducible over $\mathbb{Z}$ iff irreducible over $\mathbb{Q}$. Eisenstein: if a prime $p$ divides every non-leading coefficient, $p\nmid a_n$, $p^2\nmid a_0$, then $f$ is irreducible over $\mathbb{Q}$.",
      r"Show $x^3+3x+3$ is irreducible over $\mathbb{Q}$ by Eisenstein, and factor $x^4-1$ in $\mathbb{Q}[x]$.",
      r"$p=3$ divides $3$ and $3$, not the leading $1$, and $9\nmid 3$. Irreducible (degree $3$, alternatively no rational root). $x^4-1=(x^2-1)(x^2+1)=(x-1)(x+1)(x^2+1)$, irreducible factors over $\mathbb{Q}$.",
      r"Eisenstein $p=2$ on $x^4+2x+2$?", r"$2$ divides $2,2$, not $1$; $4\nmid 2$. Yes, irreducible over $\mathbb{Q}$.",
      r"Applying Eisenstein with $p$ dividing the leading coefficient, or concluding reducible from Eisenstein failing.",
      r"Does $x^2+x+2$ yield to a shift of Eisenstein?", r"No: $f(x+1)=x^2+3x+4$ still fails Eisenstein. It is irreducible over $\mathbb{Q}$ anyway (discriminant $-7$).",
      r"Is $\mathbb{Z}[x]$ a UFD?", r"Yes, by Gauss's lemma, though not a PID.")
    a(603, r"A Euclidean domain is an integral domain $R$ with a function $v:R\setminus\{0\}\to\mathbb{Z}_{\ge 0}$ such that for $a,b\neq 0$ there exist $q,r$ with $a=qb+r$ and $r=0$ or $v(r)<v(b)$. Then $R$ is a PID (the generator of an ideal is a minimal-$v$ element) and hence a UFD. Examples: $\mathbb{Z}$ with $v=|\,\cdot\,|$; $F[x]$ with $v=\deg$; $\mathbb{Z}[i]$ with the field norm $v(a+bi)=a^2+b^2$.",
      r"Why is $\mathbb{Z}[i]$ Euclidean? Divide $3+4i$ by $1+i$.",
      r"Norm $N(z)=z\overline{z}$ is multiplicative. Divide in $\mathbb{C}$ and round: $(3+4i)/(1+i)=(3+4i)(1-i)/2=(7+i)/2=3.5+0.5i$. Nearest Gaussian integers include $3+i$ and $4$. For $q=3+i$: $(1+i)(3+i)=2+4i$, remainder $(3+4i)-(2+4i)=1$, and $N(1)=1<N(1+i)=2$.",
      r"Is $\mathbb{Z}[x]$ Euclidean?", r"No: not even a PID.",
      r"Taking $v$ that can increase on remainders, or claiming every PID is Euclidean (open/false in general; $\mathbb{Z}[\frac{1+\sqrt{-19}}{2}]$ is a PID that is not Euclidean).",
      r"Euclidean function on $F[x]$.", r"Degree.",
      r"$F[x]$ is Euclidean even if $\deg 0$ is $-\infty$ for the zero remainder.", r"The algorithm allows $r=0$ separately.")
    a(604, r"A PID is an integral domain in which every ideal is principal. Euclidean $\Rightarrow$ PID $\Rightarrow$ UFD. $\mathbb{Z}$, $F[x]$, $\mathbb{Z}[i]$ are PIDs. $\mathbb{Z}[x]$ and $F[x,y]$ are not. In a PID, irreducible $\Leftrightarrow$ prime, and nonzero prime ideals are maximal. gcd exists and is a generator of $(a,b)$.",
      r"Why is $\mathbb{Z}[x]$ not a PID? Why is every nonzero prime ideal of $\mathbb{Z}$ maximal?",
      r"$(2,x)$ is not principal. In $\mathbb{Z}$, a nonzero prime ideal is $(p)$, and $\mathbb{Z}/(p)$ is a field, so maximal.",
      r"A generator of the ideal $(6,9,15)$ in $\mathbb{Z}$", r"$\gcd(6,9,15)=3$, so $(3)$.",
      r"Concluding $F[x,y]$ is a PID because $F[x]$ is (adjoining another variable destroys the PID property).",
      r"Is $\mathbb{Q}[x]$ a PID?", r"Yes: $F[x]$ for $F=\mathbb{Q}$.",
      r"In a PID, $(a)\cap(b)=$", r"$(lcm(a,b))$.")
    a(605, r"A UFD is a domain where every nonunit nonzero element factors into irreducibles uniquely up to order and units. PID $\Rightarrow$ UFD, not conversely: $\mathbb{Z}[x]$ is a UFD, not a PID. In a UFD, irreducible $\Leftrightarrow$ prime. $\mathbb{Z}[\sqrt{-5}]$ is not a UFD: $6=2\cdot 3=(1+\sqrt{-5})(1-\sqrt{-5})$ with two essentially different irreducible factorizations. Atomic domains need not be UFDs.",
      r"Show the two factorizations of $6$ in $\mathbb{Z}[\sqrt{-5}]$ are genuinely distinct, using the norm $N(a+b\sqrt{-5})=a^2+5b^2$.",
      r"$N(2)=4$, $N(3)=9$, $N(1\pm\sqrt{-5})=6$. Units have norm $1$, so $\pm 1$. None of $2,3,1\pm\sqrt{-5}$ are associates (norms differ or $2$ does not divide $1+\sqrt{-5}$). All four are irreducible because their norms are not composite in the image of $N$ as $N(z)N(w)$ with both $>1$.",
      r"$\mathbb{Z}[x]$ is a UFD but not a", r"PID.",
      r"Treating unique factorization of integers as automatically true in every subring of $\mathbb{C}$.",
      r"Is $F[x,y]$ a UFD?", r"Yes ($F[x]$ UFD $\Rightarrow F[x][y]$ UFD).",
      r"Associates in a UFD differ by", r"multiplication by a unit.")
    a(606, r"CRT in ring form: if $I,J$ are ideals of a unital commutative ring $R$ with $I+J=R$ (comaximal), then $I\cap J=IJ$ and $R/(I\cap J)\cong R/I\times R/J$ via $r\mapsto(r+I,r+J)$. For pairwise comaximal $I_1,\ldots,I_k$, $R/\bigcap I_k\cong\prod R/I_k$. Special case: $\mathbb{Z}/(mn)\cong\mathbb{Z}/m\times\mathbb{Z}/n$ when $\gcd(m,n)=1$; $F[x]/(fg)\cong F[x]/(f)\times F[x]/(g)$ when $\gcd(f,g)=1$.",
      r"Identify $\mathbb{Z}/12\mathbb{Z}$ with a product, and $\mathbb{R}[x]/(x^2-1)$.",
      r"$\mathbb{Z}/12\cong\mathbb{Z}/4\times\mathbb{Z}/3$ because $4,3$ coprime. $\mathbb{R}[x]/(x^2-1)=\mathbb{R}[x]/((x-1)(x+1))\cong\mathbb{R}[x]/(x-1)\times\mathbb{R}[x]/(x+1)\cong\mathbb{R}\times\mathbb{R}$.",
      r"Does $\mathbb{Z}/8\cong\mathbb{Z}/4\times\mathbb{Z}/2$?", r"No: $(4)+(2)\neq\mathbb{Z}$, so CRT does not apply. $\mathbb{Z}/8$ is cyclic; $\mathbb{Z}/4\times\mathbb{Z}/2$ is not.",
      r"Using $R/(I\cap J)\cong R/I\times R/J$ without $I+J=R$ (counterexample $I=J=(2)$ in $\mathbb{Z}$: $\mathbb{Z}/2\not\cong\mathbb{Z}/2\times\mathbb{Z}/2$).",
      r"$F[x]/(x(x-1))\cong$", r"$F\times F$.",
      r"If $I+J=R$ then there exist $i\in I$, $j\in J$ with", r"$i+j=1$, the Bézout identity for ideals.")

    # N modules
    a(607, r"A (left) module over a unital ring $R$ is an abelian group $M$ with a scalar map $R\times M\to M$ satisfying $r(m+n)=rm+rn$, $(r+s)m=rm+sm$, $(rs)m=r(sm)$, $1m=m$. $\mathbb{Z}$-modules are abelian groups. $R$-modules include $R^n$, ideals of $R$, and $R/I$. If $R$ is a field, modules are vector spaces.",
      r"Why is every abelian group uniquely a $\mathbb{Z}$-module?",
      r"$n\cdot g=g+\cdots+g$ ($n$ times), and $(-n)\cdot g=-(n\cdot g)$. Uniqueness of this structure: the axioms force it. So there is only one $\mathbb{Z}$-module structure on a given abelian group.",
      r"An ideal $I\subseteq R$ is an $R$-module via", r"the ring multiplication.",
      r"Forgetting $1m=m$ (unital module axiom), which allows pathological scalar actions.",
      r"Is $\mathbb{Z}/n\mathbb{Z}$ a $\mathbb{Z}$-module?", r"Yes: the quotient abelian group.",
      r"$R$ as a module over itself is", r"the regular module; submodules are (left) ideals.")
    a(608, r"A submodule $N\subseteq M$ is an additive subgroup with $R N\subseteq N$. Examples: subspaces; ideals as submodules of $R$; $n\mathbb{Z}\subseteq\mathbb{Z}$; $p$-torsion in an abelian group. Intersections and sums of submodules are submodules. Cyclic submodule $Rm=\{rm:r\in R\}$.",
      r"Submodules of $\mathbb{Z}$ as a $\mathbb{Z}$-module, and of $F^2$ as an $F[x]$-module via a matrix?",
      r"Submodules of $\mathbb{Z}$ are $n\mathbb{Z}$. For $F^2$ with $x$ acting by a linear operator $T$, submodules are $T$-invariant subspaces.",
      r"$2\mathbb{Z}+3\mathbb{Z}$ as a submodule of $\mathbb{Z}$", r"$\mathbb{Z}$, because $2,3$ generate $1$.",
      r"Checking additive closure but not absorption of scalars (a subgroup of an $F$-vector space that is not a subspace).",
      r"Is $\mathbb{Q}$ a submodule of $\mathbb{R}$ as $\mathbb{Z}$-modules?", r"Yes: an additive subgroup closed under $\mathbb{Z}$.",
      r"Cyclic submodule generated by $2$ in $\mathbb{Z}/8\mathbb{Z}$.", r"$\{0,2,4,6\}\cong\mathbb{Z}/4$.")
    a(609, r"If $N\subseteq M$ is a submodule, the quotient module $M/N$ is the abelian group of cosets with $r(m+N)=rm+N$. Then $M/N=0$ iff $N=M$. Examples: $\mathbb{Z}/n\mathbb{Z}$; $R/I$ as an $R$-module; $F^n/W$ for a subspace $W$. Correspondence: submodules of $M/N$ biject with submodules of $M$ containing $N$.",
      r"Identify $\mathbb{Z}/4\mathbb{Z}$ as a quotient of the $\mathbb{Z}$-module $\mathbb{Z}$, and $(\mathbb{Z}/8)/(\,4\cdot\mathbb{Z}/8\,)$.",
      r"$\mathbb{Z}/4\mathbb{Z}=\mathbb{Z}/4\mathbb{Z}$. In $\mathbb{Z}/8$, the submodule generated by $4$ is $\{0,4\}$, quotient order $4$, isomorphic to $\mathbb{Z}/4$.",
      r"$M/N$ is cyclic if $M$ is cyclic.", r"Yes: the image of a generator generates.",
      r"Defining $r(m+N)=rm+N$ when $N$ is only a subgroup not absorbing $R$ (not well-defined).",
      r"Quotient of $F^2$ by a $1$-dimensional subspace, as $F$-modules.", r"One-dimensional, $\cong F$.",
      r"If $N=0$, then $M/N\cong$", r"$M$.")
    a(610, r"An $R$-module homomorphism $\phi:M\to N$ is an additive group hom with $\phi(rm)=r\phi(m)$. Kernel is a submodule of $M$, image a submodule of $N$. First iso: $M/\ker\cong\mathrm{im}$. $\mathrm{Hom}_R(R,M)\cong M$ via $\phi\mapsto\phi(1)$. $\mathrm{Hom}_{\mathbb{Z}}(\mathbb{Z}/n,\mathbb{Z}/m)\cong\mathbb{Z}/\gcd(n,m)$.",
      r"Describe $\mathrm{Hom}_{\mathbb{Z}}(\mathbb{Z}/2,\mathbb{Z}/4)$ and a nontrivial map.",
      r"$\cong\mathbb{Z}/2$. A generator $1\bmod 2$ may go to an element of order dividing $2$ in $\mathbb{Z}/4$, i.e. $0$ or $2$. Nontrivial: $1\mapsto 2$.",
      r"$\mathrm{Hom}_F(F^n,F^m)$ is", r"$m\times n$ matrices, $F$-linear maps.",
      r"Checking additivity but not $R$-linearity (over $\mathbb{Z}$ they coincide; over $\mathbb{R}$ a group hom of $(\mathbb{R},+)$ need not be $\mathbb{R}$-linear without extra hypotheses).",
      r"Kernel of $M\to M/N$, $m\mapsto m+N$.", r"$N$.",
      r"Is $\phi:\mathbb{Z}\to\mathbb{Z}$, $\phi(n)=2n$, $\mathbb{Z}$-linear?", r"Yes, and injective, not surjective.")
    a(611, r"A set $S\subseteq M$ generates $M$ if the smallest submodule containing $S$ is $M$: every $m$ is a finite $R$-linear combination of elements of $S$. $M$ is cyclic if one element generates it: $M\cong R/I$ for $I=\mathrm{Ann}(m)$. Finitely generated: some finite $S$. $\mathbb{Q}$ is not finitely generated as a $\mathbb{Z}$-module. Nakayama concerns generation after reducing modulo the Jacobson radical.",
      r"Show $\mathbb{Z}/6\mathbb{Z}$ is cyclic as a $\mathbb{Z}$-module. Does $\{(2,0),(0,3)\}$ generate $\mathbb{Z}^2$?",
      r"Yes, generated by $[1]$. No: $\{(2,0),(0,3)\}$ generates $2\mathbb{Z}\times 3\mathbb{Z}$, index $6$ in $\mathbb{Z}^2$. The standard basis $\{(1,0),(0,1)\}$ generates $\mathbb{Z}^2$.",
      r"Cyclic $\mathbb{Z}$-modules up to iso", r"$\mathbb{Z}$ and $\mathbb{Z}/n\mathbb{Z}$.",
      r"Confusing generating as a module with generating as a ring (or as a group under multiplication).",
      r"Does $\{2,3\}$ generate $\mathbb{Z}$ as a $\mathbb{Z}$-module?", r"Yes: $3-2=1$.",
      r"Is $\mathbb{Q}$ a cyclic $\mathbb{Z}$-module?", r"No: $1$ generates only $\mathbb{Z}$; any $p/q$ generates $\frac{1}{q}\mathbb{Z}$ at best a cyclic group not all of $\mathbb{Q}$.")
    a(612, r"A free $R$-module on a set $S$ is isomorphic to $\bigoplus_{s\in S} R$, with basis $S$: every element is a unique finite $R$-linear combination of basis elements. $R^n$ is free of rank $n$. Over a commutative ring, rank is well-defined. $\mathbb{Z}/n$ is not free over $\mathbb{Z}$. Submodules of free modules over a PID are free of smaller or equal rank. Bases exist for vector spaces; not for general modules (e.g. $\mathbb{Q}$ over $\mathbb{Z}$).",
      r"Is $\mathbb{Z}^2$ free? Is $2\mathbb{Z}$ free over $\mathbb{Z}$? Is $\mathbb{Z}/2$ free over $\mathbb{Z}$?",
      r"Yes, standard basis. Yes: $\{2\}$ is a basis (unique writing $n\cdot 2$). No: any generating set is linearly dependent over $\mathbb{Z}$ because $2\cdot[1]=0$, or rank would imply a submodule of $\mathbb{Z}^k$ isomorphic to $\mathbb{Z}/2$, impossible in a torsion-free module.",
      r"Rank of $R^n$ as an $R$-module", r"$n$.",
      r"Calling every finitely generated module free (false: torsion modules).",
      r"A basis of $\mathbb{Z}$ as a $\mathbb{Z}$-module.", r"$\{1\}$, or $\{-1\}$.",
      r"Is $\mathbb{Q}$ free over $\mathbb{Z}$?", r"No: any two rationals are $\mathbb{Z}$-linearly dependent, but one element does not span.")
    a(613, r"If $F$ is a field, $F$-modules are precisely $F$-vector spaces. Submodules are subspaces, homs are linear maps, free modules are those with a basis (all vector spaces, assuming choice for the infinite case), rank is dimension. The structure theory of modules over a PID specializes to rational canonical form / Jordan form when $R=F[x]$ acting on a finite-dimensional $F$-space.",
      r"Reinterpret $T:V\to V$ linear as an $F[x]$-module. What is a cyclic submodule?",
      r"$x\cdot v=T(v)$, and $f(x)\cdot v=f(T)(v)$. A cyclic submodule $F[x]v$ is the $T$-invariant subspace spanned by $\{v,Tv,T^2v,\ldots\}$, the cyclic subspace generated by $v$.",
      r"Dimension is the module-theoretic", r"rank (for free modules / vector spaces).",
      r"Treating $\mathbb{Z}$-modules as vector spaces (no division by $n$ when $n\neq\pm 1$).",
      r"Every finitely generated module over a field is", r"free of finite rank (choose a basis).",
      r"Jordan form exists when $F$ is", r"algebraically closed (or at least contains the eigenvalues).")

    # N fields & extensions
    a(614, r"A field is a commutative unital ring in which every nonzero element is a unit (equivalently a commutative division ring). $1\neq 0$. Examples: $\mathbb{Q},\mathbb{R},\mathbb{C}$, $\mathbb{F}_p=\mathbb{Z}/p\mathbb{Z}$, $F(x)$ rational functions, $\mathbb{Q}(\sqrt{2})$. Finite fields have prime-power order. Characteristic is $0$ or prime $p$; the prime field is $\mathbb{Q}$ or $\mathbb{F}_p$.",
      r"Which of $\mathbb{Z}/4\mathbb{Z}$, $\mathbb{Z}/5\mathbb{Z}$, $\mathbb{Q}[x]/(x^2+1)$ are fields?",
      r"$\mathbb{Z}/4$ no ($2$ not invertible). $\mathbb{Z}/5$ yes. $\mathbb{Q}[x]/(x^2+1)\cong\mathbb{Q}(i)$, a field because $x^2+1$ is irreducible over $\mathbb{Q}$.",
      r"A finite integral domain is a", r"field.",
      r"Calling $\mathbb{Z}$ a field, or $\mathbb{Z}/n$ a field for composite $n$.",
      r"Characteristic of $\mathbb{Q}$ and of $\mathbb{F}_9$.", r"$0$ and $3$.",
      r"Is $F[[x]]$ a field?", r"No: $x$ is not invertible in formal power series. The Laurent series $F((x))$ is a field.")
    a(615, r"A subfield $K\subseteq F$ is a subset that is a field under the same operations (hence contains $0,1$ and is closed under $+,-,\cdot$, and inverses of nonzero elements). The intersection of subfields is a subfield. Prime field: smallest subfield, isomorphic to $\mathbb{Q}$ or $\mathbb{F}_p$. $\mathbb{Q}\subset\mathbb{R}\subset\mathbb{C}$. Intermediate fields of $\mathbb{C}/\mathbb{Q}$ are abundant.",
      r"Is $\mathbb{Q}(\sqrt{2})=\{a+b\sqrt{2}:a,b\in\mathbb{Q}\}$ a subfield of $\mathbb{R}$? Inverse of $3+2\sqrt{2}$?",
      r"Yes: closed, and $(3+2\sqrt{2})^{-1}=(3-2\sqrt{2})/(9-8)=3-2\sqrt{2}$.",
      r"Prime field of $\mathbb{R}$", r"$\mathbb{Q}$. Prime field of $\mathbb{F}_{p^n}$ is $\mathbb{F}_p$.",
      r"Checking closure under addition and multiplication but not inverses (e.g. $\mathbb{Z}$ in $\mathbb{Q}$).",
      r"Is $\mathbb{Z}[i]$ a subfield of $\mathbb{C}$?", r"No: $2$ has no inverse in $\mathbb{Z}[i]$. $\mathbb{Q}(i)$ is the subfield.",
      r"Intersection $\mathbb{Q}(\sqrt{2})\cap\mathbb{Q}(\sqrt{3})$.", r"$\mathbb{Q}$.")
    a(616, r"A field extension $K/F$ means $F$ is a subfield of $K$. Then $K$ is an $F$-vector space. Simple extension $F(\alpha)$ is the smallest subfield of $K$ containing $F$ and $\alpha$. $F(\alpha,\beta)=F(\alpha)(\beta)$. Finite extension: finite dimensional as a vector space. Algebraic extension: every element algebraic over $F$. $\mathbb{C}/\mathbb{R}$, $\mathbb{Q}(\sqrt{2})/\mathbb{Q}$, $\mathbb{C}/\mathbb{Q}$.",
      r"Describe $\mathbb{Q}(\sqrt{2})$ and $\mathbb{R}(i)$. What is $\mathbb{C}$ as an extension of $\mathbb{R}$?",
      r"$\mathbb{Q}(\sqrt{2})=\{a+b\sqrt{2}\}$. $\mathbb{R}(i)=\mathbb{C}=\{x+yi:x,y\in\mathbb{R}\}$. $[\mathbb{C}:\mathbb{R}]=2$.",
      r"$F(x)/F$ denotes", r"the field of rational functions, a purely transcendental simple extension.",
      r"Writing $F[\alpha]$ (the ring) when the problem needs the field $F(\alpha)$; they coincide iff $\alpha$ is algebraic.",
      r"Smallest field containing $\mathbb{Q}$ and $\sqrt[3]{2}$.", r"$\mathbb{Q}(\sqrt[3]{2})\subset\mathbb{R}$.",
      r"Is $\mathbb{Q}(\sqrt{2},\sqrt{3})=\mathbb{Q}(\sqrt{2}+\sqrt{3})$?", r"Yes, a standard simple-extension identity.")
    a(617, r"The degree $[K:F]$ is $\dim_F K$ (possibly $\infty$). Tower law: if $F\subseteq E\subseteq K$ then $[K:F]=[K:E][E:F]$ (cardinal product if infinite). $[F(\alpha):F]=\deg m_\alpha$ when $\alpha$ is algebraic. $[\mathbb{C}:\mathbb{R}]=2$, $[\mathbb{R}:\mathbb{Q}]=\infty$, $[\mathbb{Q}(\sqrt[3]{2}):\mathbb{Q}]=3$. If $[K:F]$ is prime, there is no proper intermediate field.",
      r"Compute $[\mathbb{Q}(\sqrt{2},\sqrt{3}):\mathbb{Q}]$ by a tower.",
      r"$[\mathbb{Q}(\sqrt{2}):\mathbb{Q}]=2$. $x^2-3$ remains irreducible over $\mathbb{Q}(\sqrt{2})$ (else $\sqrt{3}\in\mathbb{Q}(\sqrt{2})$), so $[\mathbb{Q}(\sqrt{2},\sqrt{3}):\mathbb{Q}(\sqrt{2})]=2$, product $4$. Basis $\{1,\sqrt{2},\sqrt{3},\sqrt{6}\}$.",
      r"$[K:F]=1$ iff", r"$K=F$.",
      r"Adding degrees in a tower instead of multiplying.",
      r"$[\mathbb{Q}(\sqrt[3]{2}):\mathbb{Q}]$.", r"$3$, min poly $x^3-2$.",
      r"Can a degree-$6$ extension have an intermediate field of degree $5$ over the base?", r"No: $5\nmid 6$.")
    a(618, r"An element $\alpha\in K$ is algebraic over $F$ if $f(\alpha)=0$ for some nonzero $f\in F[x]$. Then there is a unique monic polynomial of least degree with this property, the minimal polynomial $m_\alpha$, which is irreducible, and $F(\alpha)\cong F[x]/(m_\alpha)$ with $[F(\alpha):F]=\deg m_\alpha$. A finite extension is algebraic. Sums and products of algebraic elements are algebraic.",
      r"Show $\sqrt{2}+\sqrt{3}$ is algebraic over $\mathbb{Q}$ by producing a polynomial.",
      r"Let $\alpha=\sqrt{2}+\sqrt{3}$. $\alpha^2=5+2\sqrt{6}$, $(\alpha^2-5)^2=24$, $\alpha^4-10\alpha^2+1=0$. So algebraic, degree dividing $4$ (in fact $4$).",
      r"$\sqrt[4]{2}$ is algebraic over $\mathbb{Q}$ of degree", r"$4$: min poly $x^4-2$ (Eisenstein $p=2$).",
      r"Producing a polynomial that $\alpha$ satisfies and calling its degree the degree of $\alpha$ without proving irreducibility.",
      r"Is $i$ algebraic over $\mathbb{R}$?", r"Yes, $x^2+1$. Degree $1$ over $\mathbb{C}$, $2$ over $\mathbb{R}$.",
      r"Algebraic over $\mathbb{Q}$: $e^{2\pi i/5}$.", r"Yes, a root of the $5$th cyclotomic polynomial.")
    a(619, r"An element $\alpha$ is transcendental over $F$ if it is not algebraic: no nonzero polynomial in $F[x]$ vanishes at $\alpha$. Then $F[\alpha]\cong F[x]$ and $F(\alpha)\cong F(x)$, and $[F(\alpha):F]=\infty$. Over $\mathbb{Q}$, $e$ and $\pi$ are transcendental (Hermite, Lindemann). Transcendence of $\pi$ implies a circle cannot be squared with ruler and compass. $x\in F(x)$ is transcendental over $F$.",
      r"Why is $[F(x):F]=\infty$? Show $1,x,x^2,\ldots$ are linearly independent over $F$.",
      r"A finite linear combination $\sum_{k=0}^n a_k x^k=0$ in $F(x)$ is a polynomial identity, so all $a_k=0$. Hence infinitely many independent powers, infinite degree.",
      r"Is $\pi^2$ transcendental over $\mathbb{Q}$?", r"Yes: if algebraic, $\pi$ would be algebraic (a square root of an algebraic is algebraic).",
      r"Concluding $\alpha$ transcendental because it is irrational (algebraic irrationals exist: $\sqrt{2}$).",
      r"$e+\pi$ is known to be transcendental?", r"Open. At least one of $e+\pi$, $e\pi$ is transcendental.",
      r"$F(\pi)/F$ for $F=\mathbb{R}$. Is $\pi$ transcendental over $\mathbb{R}$?", r"No: $\pi\in\mathbb{R}$, min poly $x-\pi$, algebraic of degree $1$.")
    a(620, r"The minimal polynomial $m_{\alpha,F}$ of an algebraic $\alpha$ over $F$ is the unique monic generator of the kernel of $F[x]\to K$, $f\mapsto f(\alpha)$. It is monic irreducible, and it divides every polynomial in $F[x]$ that vanishes at $\alpha$. Degree of $\alpha$ is $\deg m_\alpha$. Changing $F$ can drop the degree: $m_{i,\mathbb{Q}}=x^2+1$, $m_{i,\mathbb{R}}=x^2+1$, $m_{i,\mathbb{C}}=x-i$.",
      r"Minimal polynomial of $\sqrt{2}+\sqrt{3}$ over $\mathbb{Q}$, and of $\sqrt{2}$ over $\mathbb{Q}(\sqrt{2})$.",
      r"$x^4-10x^2+1$ is monic of degree $4=[\mathbb{Q}(\sqrt{2},\sqrt{3}):\mathbb{Q}]$ and $\mathbb{Q}(\sqrt{2}+\sqrt{3})=\mathbb{Q}(\sqrt{2},\sqrt{3})$, hence it is the min poly. Over $\mathbb{Q}(\sqrt{2})$, $\sqrt{2}$ has min poly $x-\sqrt{2}$.",
      r"Min poly of $e^{2\pi i/3}$ over $\mathbb{Q}$", r"$x^2+x+1$ (cyclotomic $\Phi_3$).",
      r"Taking a polynomial that $\alpha$ satisfies without making it monic or irreducible (e.g. $x^2-2$ is min poly of $\sqrt{2}$, not $2x^2-4$).",
      r"Min poly of $2\sqrt{2}$ over $\mathbb{Q}$.", r"$x^2-8$.",
      r"Does $x^2-2$ remain the min poly of $\sqrt{2}$ over $\mathbb{R}$?", r"No: over $\mathbb{R}$ it splits, min poly is $x-\sqrt{2}$.")
    a(621, r"Connection: $\alpha$ algebraic over $F$ of degree $n$ iff $m_\alpha$ is irreducible of degree $n$ iff $\{1,\alpha,\ldots,\alpha^{n-1}\}$ is an $F$-basis of $F(\alpha)$. Adjoining a root of an irreducible $f$ of degree $n$ produces an extension of degree $n$. Reducible polynomials still have roots in some extension, but adjoining one root of a reducible polynomial gives degree equal to an irreducible factor's degree.",
      r"Degree of $\mathbb{Q}(\sqrt[3]{2})$ and of $\mathbb{Q}(\omega\sqrt[3]{2})$ where $\omega=e^{2\pi i/3}$. Both roots of $x^3-2$.",
      r"Both have degree $3$ over $\mathbb{Q}$ because $x^3-2$ is irreducible (Eisenstein $2$). The splitting field $\mathbb{Q}(\sqrt[3]{2},\omega)$ has degree $6$.",
      r"If $f$ irreducible of degree $n$ and $f(\alpha)=0$, then $[F(\alpha):F]=$", r"$n$.",
      r"Adjoining a root of a reducible polynomial and claiming the degree is $\deg f$ (it is the degree of the irr factor that actually vanishes).",
      r"$x^4-1$ at $\alpha=-1$: $[\mathbb{Q}(-1):\mathbb{Q}]=$", r"$1$, because the irr factor is $x+1$ of degree $1$.",
      r"Can an irreducible cubic have a root in a quadratic extension?", r"No: degree $3$ cannot divide $2$.")
    a(622, r"A splitting field of $f\in F[x]$ over $F$ is an extension $K/F$ in which $f$ factors into linear factors and $K$ is generated by the roots of $f$. It exists, is unique up to $F$-isomorphism, and $[K:F]$ divides $n!$ and is a multiple of $\deg$ of each irr factor, for $\deg f=n$. Example: splitting field of $x^2-2$ over $\mathbb{Q}$ is $\mathbb{Q}(\sqrt{2})$; of $x^3-2$ is $\mathbb{Q}(\sqrt[3]{2},\omega)$ of degree $6$.",
      r"Splitting field of $x^2+1$ over $\mathbb{R}$ and of $x^3-2$ over $\mathbb{Q}$. Degrees?",
      r"Over $\mathbb{R}$: $\mathbb{C}=\mathbb{R}(i)$, degree $2$. Over $\mathbb{Q}$: $\mathbb{Q}(\sqrt[3]{2},\omega)$, degree $6=3\cdot 2$ (real cube root degree $3$, then cyclotomic $x^2+x+1$).",
      r"Splitting field of $(x^2-2)(x^2-3)$ over $\mathbb{Q}$", r"$\mathbb{Q}(\sqrt{2},\sqrt{3})$, degree $4$.",
      r"Stopping after adjoining one root of an irr cubic that has two complex roots (the splitting field is larger than the real simple extension).",
      r"Does $x^2-2$ split over $\mathbb{Q}(\sqrt{2})$?", r"Yes: $(x-\sqrt{2})(x+\sqrt{2})$.",
      r"Degree of a splitting field of a quadratic over $F$", r"$1$ if it splits already, else $2$.")
    a(623, r"An algebraic closure $\overline{F}$ of $F$ is an algebraic extension that is algebraically closed: every nonconstant polynomial in $\overline{F}[x]$ has a root in $\overline{F}$ (equivalently splits completely). Existence and uniqueness up to (non-canonical) isomorphism use Zorn. $\mathbb{C}$ is algebraically closed (FTA) and is an algebraic closure of $\mathbb{R}$, but not of $\mathbb{Q}$ (transcendentals). The algebraic numbers $\overline{\mathbb{Q}}\subset\mathbb{C}$ form an algebraic closure of $\mathbb{Q}$.",
      r"Why is $\mathbb{C}$ not an algebraic closure of $\mathbb{Q}$? What is?",
      r"$\pi\in\mathbb{C}$ is transcendental over $\mathbb{Q}$, so $\mathbb{C}/\mathbb{Q}$ is not algebraic. $\overline{\mathbb{Q}}=\{z\in\mathbb{C}:z\text{ algebraic over }\mathbb{Q}\}$ is an algebraic closure of $\mathbb{Q}$.",
      r"Algebraic closure of $\mathbb{R}$", r"$\mathbb{C}$, degree $2$.",
      r"Claiming every algebraically closed field is $\mathbb{C}$, or that $\overline{\mathbb{Q}}=\mathbb{C}$.",
      r"Is a finite field algebraically closed?", r"No: $x^{q}-x$ has $q$ roots, but $x^q-x+1$ or simply the polynomial $x^q-x$ does not exhaust all; more cleanly $x^{q^n}-x$ for $n>1$ introduces new roots. A finite field of order $q$ does not contain a root of an irreducible of degree $>1$.",
      r"Every polynomial over $\mathbb{C}$ of positive degree has", r"a root in $\mathbb{C}$ (FTA).")
    a(624, r"The field $\mathbb{F}_p=\mathbb{Z}/p\mathbb{Z}$ for $p$ prime is the unique field with $p$ elements (up to iso), characteristic $p$. Arithmetic is mod $p$. Freshman's dream: $(a+b)^{p}=a^p+b^p$ in characteristic $p$ (binomial coefficients $\binom{p}{k}$ divisible by $p$ for $0<k<p$). Fermat: $a^p=a$ for all $a\in\mathbb{F}_p$. The multiplicative group $\mathbb{F}_p^\times$ is cyclic of order $p-1$.",
      r"Compute $(1+2)^3$ vs $1^3+2^3$ in $\mathbb{F}_3$, and find a generator of $\mathbb{F}_7^\times$.",
      r"In $\mathbb{F}_3$, $p=3$: $(0)^3=0=1+8\equiv 1+2=0$. Explicitly $(1+2)^3=0^3=0$ and $1+8=9\equiv 0$. Generator of $\mathbb{F}_7^\times$: $3$ (primitive root, orders to $6$).",
      r"$|\mathbb{F}_p^\times|$ equals", r"$p-1$.",
      r"Using division by $p$ in $\mathbb{F}_p$, or writing $\mathbb{F}_4=\mathbb{Z}/4\mathbb{Z}$.",
      r"Inverse of $3$ in $\mathbb{F}_{11}$.", r"$4$, because $12\equiv 1$.",
      r"Is every nonzero element of $\mathbb{F}_{11}$ a square?", r"No: $(p-1)/2=5$ residues. $2$ is a nonresidue? $1^2=1$, $2^2=4$, $3^2=9$, $4^2=5$, $5^2=3$. Residues $1,3,4,5,9$. $2$ is a nonresidue.")
    a(625, r"For each prime $p$ and $n\ge 1$ there is a unique (up to iso) finite field $\mathbb{F}_{p^n}$ of order $p^n$, namely the splitting field of $x^{p^n}-x$ over $\mathbb{F}_p$. It is a degree-$n$ extension of $\mathbb{F}_p$. $\mathbb{F}_{p^n}^\times$ is cyclic of order $p^n-1$. Subfields of $\mathbb{F}_{p^n}$ are $\mathbb{F}_{p^d}$ for $d\mid n$, unique for each $d$. Construction: $\mathbb{F}_{p^n}\cong\mathbb{F}_p[x]/(f)$ for any irreducible $f$ of degree $n$.",
      r"Construct $\mathbb{F}_4$ as $\mathbb{F}_2[x]/(x^2+x+1)$ and list the subfields of $\mathbb{F}_{16}$.",
      r"$x^2+x+1$ is the unique irr quadratic over $\mathbb{F}_2$. Let $\omega=\bar x$, then $\omega^2=\omega+1$ (char $2$), $\mathbb{F}_4=\{0,1,\omega,\omega+1\}$ with $\omega^3=1$. Subfields of $\mathbb{F}_{16}=\mathbb{F}_{2^4}$: $d\mid 4$ so $\mathbb{F}_2$, $\mathbb{F}_4$, $\mathbb{F}_{16}$.",
      r"$|\mathbb{F}_{p^n}^\times|$ equals", r"$p^n-1$, cyclic.",
      r"Writing $\mathbb{F}_8\subseteq\mathbb{F}_{16}$ (orders $8=2^3$, $16=2^4$, $3\nmid 4$, so no containment).",
      r"Does $\mathbb{F}_{9}$ contain $\mathbb{F}_{3}$? $\mathbb{F}_{27}$?",
      r"$9=3^2$, so yes $\mathbb{F}_3\subset\mathbb{F}_9$. $27=3^3$, $2\nmid 3$, so $\mathbb{F}_9\not\subseteq\mathbb{F}_{27}$.",
      r"An irreducible cubic over $\mathbb{F}_2$ gives a field of order", r"$8=\mathbb{F}_8$. Example $x^3+x+1$.")

    return F
